INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4v7Y70NSZVO', 1, '{"title":"一难","description":"<p>1、曰。十二经皆有动脉。独取寸口。以决五脏六腑死生吉凶之法。何谓也。然。寸口者。脉之大会。手太阴之脉动也。人一呼脉行三寸。一吸脉行三寸。呼吸定息。脉行六寸。人一日一夜。凡一万三千五百息。脉行五十度。周于身。漏水下百刻。营卫行阳二十五度。行阴亦二十五度。为一周也。故五十度复会于手太阴。寸口者。五脏六腑之所终始。故法取于寸口也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100001}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。十二经皆有动脉。独取寸口。以决五脏六腑死生吉凶之法。何谓也。然。寸口者。脉之大会。手太阴之脉动也。人一呼脉行三寸。一吸脉行三寸。呼吸定息。脉行六寸。人一日一夜。凡一万三千五百息。脉行五十度。周于身。漏水下百刻。营卫行阳二十五度。行阴亦二十五度。为一周也。故五十度复会于手太阴。寸口者。五脏六腑之所终始。故法取于寸口也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5SN2vhHWk3J', 1, '{"title":"二难","description":"<p>1、曰。脉有尺寸。何谓也。然。尺寸者。脉之大要会也。从关至尺是尺内。阴之所治也。从关至鱼际是寸内。阳之所治也。故分寸为尺。分尺为寸。故阴得尺内一寸。阳得寸内九分。尺寸终始。一寸九分。故曰尺寸也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100002}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有尺寸。何谓也。然。尺寸者。脉之大要会也。从关至尺是尺内。阴之所治也。从关至鱼际是寸内。阳之所治也。故分寸为尺。分尺为寸。故阴得尺内一寸。阳得寸内九分。尺寸终始。一寸九分。故曰尺寸也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Niqp0TpCfqf', 1, '{"title":"三难","description":"<p>1、曰。脉有太过。有不及。有阴阳相乘。有覆有溢。有关有格。何谓也。然。关之前者。阳之动也。脉当见九分而浮。过者。法曰太过。减者。法曰不及。遂上鱼为溢。为外关内格。此阴乘之脉也。关之后者。阴之动也。脉当见一寸而沉。过者。法曰太过。减者。法曰不及。遂入尺为覆。为内关外格。此阳乘之脉也。故曰覆溢。是其真脏之脉。人不病而死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100003}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有太过。有不及。有阴阳相乘。有覆有溢。有关有格。何谓也。然。关之前者。阳之动也。脉当见九分而浮。过者。法曰太过。减者。法曰不及。遂上鱼为溢。为外关内格。此阴乘之脉也。关之后者。阴之动也。脉当见一寸而沉。过者。法曰太过。减者。法曰不及。遂入尺为覆。为内关外格。此阳乘之脉也。故曰覆溢。是其真脏之脉。人不病而死也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('71L3XW5G7n9', 1, '{"title":"四难","description":"<p>1、曰。脉有阴阳之法。何谓也。然。呼出心与肺。吸入肾与肝。呼吸之间。脾也其脉在中。浮者阳也。沉者阴也。故曰阴阳也。</p><p>2、心肺俱浮。何以别之。然。浮而大散者心也浮而短涩者肺也。</p><p>3、肾肝俱沉。何以别之。然。牢而长者肝也。按之濡。举指来实者肾也。脾者中州。故其脉在中。是阴阳之法也。脉有一阴一阳。一阴二阳。一阴三阳。有一阳一阴。一阳二阴。一阳三阴。</p><p>4、如此之言。寸口有六脉俱动邪。然。此言者。非有六脉俱动也。谓浮。沉。长。短。滑。涩也。浮者阳也。滑者阳也。长者阳也。沉者阴也。短者阴也。涩者阴也。所谓一阴一阳者。谓脉来沉而滑也。一阴二阳者。谓脉来沉滑而长也。一阴三阳者。谓脉来浮滑而长。时一沉也。所谓一阳一阴者。谓脉来浮而涩也。一阳二阴者。谓脉来长而沉涩也。一阳三阴者。谓脉来沉涩而短。时一浮也。各以其经所在。名病顺逆也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100004}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有阴阳之法。何谓也。然。呼出心与肺。吸入肾与肝。呼吸之间。脾也其脉在中。浮者阳也。沉者阴也。故曰阴阳也。 2、心肺俱浮。何以别之。然。浮而大散者心也浮而短涩者肺也。 3、肾肝俱沉。何以别之。然。牢而长者肝也。按之濡。举指来实者肾也。脾者中州。故其脉在中。是阴阳之法也。脉有一阴一阳。一阴二阳。一阴三阳。有一阳一阴。一阳二阴。一阳三阴。 4、如此之言。寸口有六脉俱动邪。然。此言者。非有六脉俱动也。谓浮。沉。长。短。滑。涩也。浮者阳也。滑者阳也。长者阳也。沉者阴也。短者阴也。涩者阴也。所谓一阴一阳者。谓脉来沉而滑也。一阴二阳者。谓脉来沉滑而长也。一阴三阳者。谓脉来浮滑而长。时一沉也。所谓一阳一阴者。谓脉来浮而涩也。一阳二阴者。谓脉来长而沉涩也。一阳三阴者。谓脉来沉涩而短。时一浮也。各以其经所在。名病顺逆也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4ZToD5Jt164', 1, '{"title":"五难","description":"<p>1、曰。脉有轻重。何谓也。然。初持脉。如三菽之重。与皮毛相得者。肺部也。如六菽之重。与血脉相得者。心部也。如九菽之重。与肌肉相得者。脾部也。如十二菽之重。与筋平者。肝部也。按之至骨。举指来疾者。肾部也。故曰轻重也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100005}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有轻重。何谓也。然。初持脉。如三菽之重。与皮毛相得者。肺部也。如六菽之重。与血脉相得者。心部也。如九菽之重。与肌肉相得者。脾部也。如十二菽之重。与筋平者。肝部也。按之至骨。举指来疾者。肾部也。故曰轻重也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b3DxdOH3DyY', 1, '{"title":"六难","description":"<p>1、曰。脉有阴盛阳虚。阳盛阴虚。何谓也。然。浮之损小。沉之实大。故曰阴盛阳虚。沉之损小。浮之实大。故曰阳盛阴虚。是阴阳虚实之意也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100006}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有阴盛阳虚。阳盛阴虚。何谓也。然。浮之损小。沉之实大。故曰阴盛阳虚。沉之损小。浮之实大。故曰阳盛阴虚。是阴阳虚实之意也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W7bM78OhZew', 1, '{"title":"七难","description":"<p>1、曰。经言少阳之至。乍大乍小。乍短乍长。阳明之至。浮大而短。太阳之至。洪大而长。少阴之至。紧大而长。太阴之至。紧细而长。厥阴之至。沉短而紧。此六者。是平脉那。将病脉耶。然。皆王脉也。</p><p>2、其气以何月。各王几日。然。冬至之后。初得甲子少阳王。复得甲子阳明王。复得甲子太阳王。复得甲子少阴王。复得甲子太阴王。复得甲子厥阴王。王各六十日。六六三百六十日。以成一岁。此三阳三阴之王时日大要也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100007}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。经言少阳之至。乍大乍小。乍短乍长。阳明之至。浮大而短。太阳之至。洪大而长。少阴之至。紧大而长。太阴之至。紧细而长。厥阴之至。沉短而紧。此六者。是平脉那。将病脉耶。然。皆王脉也。 2、其气以何月。各王几日。然。冬至之后。初得甲子少阳王。复得甲子阳明王。复得甲子太阳王。复得甲子少阴王。复得甲子太阴王。复得甲子厥阴王。王各六十日。六六三百六十日。以成一岁。此三阳三阴之王时日大要也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d2TVrQIHYWO', 1, '{"title":"八难","description":"<p>1、曰。寸口脉平而死者。何谓也。然。诸十二经脉者。皆系于生气之原。所谓生气之原者。谓十二经之根本也。谓肾间动气也。此五脏六腑之本。十二经脉之根。呼吸之门。三焦之原。一名守邪之神。故气者。人之根本也。根绝则茎叶枯矣。寸口脉平而死者。生气独绝于内也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100008}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。寸口脉平而死者。何谓也。然。诸十二经脉者。皆系于生气之原。所谓生气之原者。谓十二经之根本也。谓肾间动气也。此五脏六腑之本。十二经脉之根。呼吸之门。三焦之原。一名守邪之神。故气者。人之根本也。根绝则茎叶枯矣。寸口脉平而死者。生气独绝于内也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Qv91AdOD6H', 1, '{"title":"九难","description":"<p>1、曰。何以别知脏腑之病耶。然。数者腑也。迟者脏也。数则为热。迟则为寒。诸阳为热。诸阴为寒。故以别知脏腑之病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100009}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。何以别知脏腑之病耶。然。数者腑也。迟者脏也。数则为热。迟则为寒。诸阳为热。诸阴为寒。故以别知脏腑之病也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XdQ0dfKagOt', 1, '{"title":"十难","description":"<p>1、曰。一脉为十变者。何谓也。然。五邪刚柔相逢之意也。假令心脉急甚者。肝邪干心也。心脉微急者。胆邪干小肠也。心脉大甚者。心邪自干心也。心脉微大者。小肠邪自干小肠也。心脉缓甚者。脾邪干心也。心脉微缓者。胃邪于小肠也。心脉涩甚者。肺邪干心也。心脉微涩者。大肠邪干小肠也。心脉沉甚者。肾邪干心也。心脉微沉者。膀胱邪干小肠也。五脏各有刚柔邪。故令一脉辄变为十也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100010}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。一脉为十变者。何谓也。然。五邪刚柔相逢之意也。假令心脉急甚者。肝邪干心也。心脉微急者。胆邪干小肠也。心脉大甚者。心邪自干心也。心脉微大者。小肠邪自干小肠也。心脉缓甚者。脾邪干心也。心脉微缓者。胃邪于小肠也。心脉涩甚者。肺邪干心也。心脉微涩者。大肠邪干小肠也。心脉沉甚者。肾邪干心也。心脉微沉者。膀胱邪干小肠也。五脏各有刚柔邪。故令一脉辄变为十也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F56sQb5MpOw', 1, '{"title":"十一难","description":"<p>1、曰。经言脉不满五十动而一止。一脏无气者。何脏也。然。人吸者随阴入。呼者因阳出。今吸不能至肾。至肝而还。故知一脏无气者。肾气先尽也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100011}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言脉不满五十动而一止。一脏无气者。何脏也。然。人吸者随阴入。呼者因阳出。今吸不能至肾。至肝而还。故知一脏无气者。肾气先尽也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8h9L46yCCoe', 1, '{"title":"十二难","description":"<p>1、曰。经言五脏脉已绝于内。用针者反实其外。五脏脉已绝于外。用针者反实其内。内外之绝。何以别之。然。五脏脉已绝于内者。肾肝气已绝于内也。而医反补其心肺。五脏脉已绝于外者。心肺气已绝于外也。而医反补其肾肝。阳绝补阴。阴绝补阳。是谓实实虚虚。损不足而益有余。如此死者。医杀之耳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100012}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言五脏脉已绝于内。用针者反实其外。五脏脉已绝于外。用针者反实其内。内外之绝。何以别之。然。五脏脉已绝于内者。肾肝气已绝于内也。而医反补其心肺。五脏脉已绝于外者。心肺气已绝于外也。而医反补其肾肝。阳绝补阴。阴绝补阳。是谓实实虚虚。损不足而益有余。如此死者。医杀之耳。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9fZG3HcpKZg', 1, '{"title":"十三难","description":"<p>1、曰。经言见其色而不得其脉。反得相胜之脉者即死。得相生之脉者。病即自己。色之与脉当参相应。为之奈何。然。五脏有五色。皆见于面。亦当与寸口。尺内相应。假令色青。其脉当弦而急。色赤。其脉浮大而散。色黄。其脉中缓而大。色白。其脉浮涩而短。色黑。其脉沉濡而滑。此所谓五色之与脉。当参相应也。脉数。尺之皮肤亦数。脉急。尺之皮肤亦急。脉缓。尺之皮肤亦缓。脉涩。尺之皮肤亦涩。脉滑。尺之皮肤亦滑。五脏各有声。色。臭。味。当与寸口。尺内相应。其不应者病也。假令色青。其脉浮涩而短。若大而缓为相胜。浮大而散。若小而滑为相生也。经言知一为下工。知二为中工。知三为上工。上工者十全九。中工者十全七。下工者十全六。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100013}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言见其色而不得其脉。反得相胜之脉者即死。得相生之脉者。病即自己。色之与脉当参相应。为之奈何。然。五脏有五色。皆见于面。亦当与寸口。尺内相应。假令色青。其脉当弦而急。色赤。其脉浮大而散。色黄。其脉中缓而大。色白。其脉浮涩而短。色黑。其脉沉濡而滑。此所谓五色之与脉。当参相应也。脉数。尺之皮肤亦数。脉急。尺之皮肤亦急。脉缓。尺之皮肤亦缓。脉涩。尺之皮肤亦涩。脉滑。尺之皮肤亦滑。五脏各有声。色。臭。味。当与寸口。尺内相应。其不应者病也。假令色青。其脉浮涩而短。若大而缓为相胜。浮大而散。若小而滑为相生也。经言知一为下工。知二为中工。知三为上工。上工者十全九。中工者十全七。下工者十全六。此之谓也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0axSWCTEctJ', 1, '{"title":"十四难","description":"<p>1、曰。脉有损。至。何谓也。然。至之脉。一呼再至曰平。三至曰离经。四至曰夺精。五至曰死。六至曰命绝。此至之脉也。何谓损。一呼一至曰离经。再呼一至曰夺精。三呼一至曰死。四呼一至曰命绝。此损之脉也。至脉从下上。损脉从上下也。</p><p>2、损脉之为病奈何。然。一损损于皮毛。皮聚而毛落。二损损于血脉。血脉虚少。不能荣于五脏六腑。三损损于肌肉。肌肉消瘦。饮食不能为肌肤。四损损于筋。筋缓不能自收持。五损损于骨。骨痿不能起于床。反此者。至脉之病也。从上下者。骨痿不能起于床者死。从下上者。皮聚而毛落者死。</p><p>3、治损之法奈何。然。损其肺者。益其气。损其心者。调其荣卫。损其脾者。调其饮食。适其寒温。损其肝者。缓其中。损其肾者。益其精。此治损之法也。</p><p>4、脉有一呼再至。一吸再至。有一呼三至。一吸三至。有一呼四至。一吸四至。有一呼五至。一吸五至。一呼六至。一吸六至。有一呼一至。一吸一至。有再呼一至。再吸一至。有呼吸再至。</p><p>5、脉来如此。何以别知其病也。然。脉来一呼再至。一吸再至。不大不小曰平。一呼三至。一吸三至。为适得其病。前大后小。即头痛。目眩。前小后大。即胸满。短气。</p><p>6、一呼四至。一吸四至。病欲甚。脉洪大者。苦烦满。沉细者。腹中痛。滑者。伤热。涩者。中雾露。</p><p>7、一呼五至。一吸五至。其人当困。沉细夜加。浮大昼加。不大不小。虽困可治。其有大小者。为难治。</p><p>8、一呼六至。一吸六至。为死脉也。沉细夜死。浮大昼死。</p><p>9、一呼一至。一吸一至。名曰损。人虽能行。犹当着床。所以然者。血气皆不足故也。</p><p>10、再呼一至。再吸一至。$l{呼吸再至}名曰无魂。无魂者当死也。人虽能行。名曰行尸。</p><p>11、上部有脉。下部无脉。其人当吐。不吐者死。上部无脉。下部有脉。虽困无能为害。所以然者。人之有尺。譬如树之有根。枝叶虽枯槁。根本将自生。脉有根本。人有元气。故知不死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100014}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有损。至。何谓也。然。至之脉。一呼再至曰平。三至曰离经。四至曰夺精。五至曰死。六至曰命绝。此至之脉也。何谓损。一呼一至曰离经。再呼一至曰夺精。三呼一至曰死。四呼一至曰命绝。此损之脉也。至脉从下上。损脉从上下也。 2、损脉之为病奈何。然。一损损于皮毛。皮聚而毛落。二损损于血脉。血脉虚少。不能荣于五脏六腑。三损损于肌肉。肌肉消瘦。饮食不能为肌肤。四损损于筋。筋缓不能自收持。五损损于骨。骨痿不能起于床。反此者。至脉之病也。从上下者。骨痿不能起于床者死。从下上者。皮聚而毛落者死。 3、治损之法奈何。然。损其肺者。益其气。损其心者。调其荣卫。损其脾者。调其饮食。适其寒温。损其肝者。缓其中。损其肾者。益其精。此治损之法也。 4、脉有一呼再至。一吸再至。有一呼三至。一吸三至。有一呼四至。一吸四至。有一呼五至。一吸五至。一呼六至。一吸六至。有一呼一至。一吸一至。有再呼一至。再吸一至。有呼吸再至。 5、脉来如此。何以别知其病也。然。脉来一呼再至。一吸再至。不大不小曰平。一呼三至。一吸三至。为适得其病。前大后小。即头痛。目眩。前小后大。即胸满。短气。 6、一呼四至。一吸四至。病欲甚。脉洪大者。苦烦满。沉细者。腹中痛。滑者。伤热。涩者。中雾露。 7、一呼五至。一吸五至。其人当困。沉细夜加。浮大昼加。不大不小。虽困可治。其有大小者。为难治。 8、一呼六至。一吸六至。为死脉也。沉细夜死。浮大昼死。 9、一呼一至。一吸一至。名曰损。人虽能行。犹当着床。所以然者。血气皆不足故也。 10、再呼一至。再吸一至。$l{呼吸再至}名曰无魂。无魂者当死也。人虽能行。名曰行尸。 11、上部有脉。下部无脉。其人当吐。不吐者死。上部无脉。下部有脉。虽困无能为害。所以然者。人之有尺。譬如树之有根。枝叶虽枯槁。根本将自生。脉有根本。人有元气。故知不死。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zaf2wXvxleI', 1, '{"title":"十五难","description":"<p>1、曰。经言春脉弦。夏脉钩。秋脉毛。冬脉石。是王脉耶。将病脉也。然。弦。钩。毛。石者。四时之脉也。</p><p>2、春脉弦者。肝东方木也。万物始生。未有枝叶。故其脉之来。濡弱而长。故曰弦。</p><p>3、夏脉钩者。心南方火也。万物之所茂。垂枝布叶。皆下曲如钩。故其脉之来疾去迟。故曰钩。</p><p>4、秋脉毛者。肺西方金也。万物之所终。草木华叶。皆秋而落。其枝独在。若毫毛也。故其脉之来。轻虚以浮。故曰毛。</p><p>5、冬脉石者。肾北方水也。万物之所藏也。盛冬之时。水凝如石。故其脉之来。沉濡而滑。故曰石。此四时之脉也。</p><p>6、如有变奈何。然。春脉弦。反者为病。</p><p>7、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。气来厌厌聂聂。如循榆叶曰平。益实而滑。如循长竿曰病。急而劲益强。如新张弓弦曰死。春脉微弦曰平。弦多胃气少曰病。但弦无胃气曰死。春以胃气为本。夏脉钩。反者为病。</p><p>8、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来累累如环。如循琅玕曰平。来而益数。如鸡举足者曰病。前曲后居。如操带钩曰死。夏脉微钩曰平。钩多胃气少曰病。但钩无胃气曰死。夏以胃气为本。秋脉毛。反者为病。</p><p>9、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来蔼蔼如车盖。按之益大曰平。不上不下。如循鸡羽曰病。按之萧索。如风吹毛曰死。秋脉微毛曰平。毛多胃气少曰病。但毛无胃气。曰死。秋以胃气为本。冬脉石。反者为病。</p><p>10、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。脉来上大下兑。濡滑如雀之喙。曰平。啄啄连属。其中微曲。曰病。来如解索。去如弹石。曰死。冬脉微石。曰平。石多胃气少。曰病。但石无胃气。曰死。冬以胃气为本。胃者。水谷之海。主禀。四时皆以胃气为本。是谓四时之变病。死生之要会也。脾者。中州也。其平和不可得见。衰乃见耳。来如雀之啄。如水之下漏。是脾衰之见也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100015}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言春脉弦。夏脉钩。秋脉毛。冬脉石。是王脉耶。将病脉也。然。弦。钩。毛。石者。四时之脉也。 2、春脉弦者。肝东方木也。万物始生。未有枝叶。故其脉之来。濡弱而长。故曰弦。 3、夏脉钩者。心南方火也。万物之所茂。垂枝布叶。皆下曲如钩。故其脉之来疾去迟。故曰钩。 4、秋脉毛者。肺西方金也。万物之所终。草木华叶。皆秋而落。其枝独在。若毫毛也。故其脉之来。轻虚以浮。故曰毛。 5、冬脉石者。肾北方水也。万物之所藏也。盛冬之时。水凝如石。故其脉之来。沉濡而滑。故曰石。此四时之脉也。 6、如有变奈何。然。春脉弦。反者为病。 7、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。气来厌厌聂聂。如循榆叶曰平。益实而滑。如循长竿曰病。急而劲益强。如新张弓弦曰死。春脉微弦曰平。弦多胃气少曰病。但弦无胃气曰死。春以胃气为本。夏脉钩。反者为病。 8、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来累累如环。如循琅玕曰平。来而益数。如鸡举足者曰病。前曲后居。如操带钩曰死。夏脉微钩曰平。钩多胃气少曰病。但钩无胃气曰死。夏以胃气为本。秋脉毛。反者为病。 9、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来蔼蔼如车盖。按之益大曰平。不上不下。如循鸡羽曰病。按之萧索。如风吹毛曰死。秋脉微毛曰平。毛多胃气少曰病。但毛无胃气。曰死。秋以胃气为本。冬脉石。反者为病。 10、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。脉来上大下兑。濡滑如雀之喙。曰平。啄啄连属。其中微曲。曰病。来如解索。去如弹石。曰死。冬脉微石。曰平。石多胃气少。曰病。但石无胃气。曰死。冬以胃气为本。胃者。水谷之海。主禀。四时皆以胃气为本。是谓四时之变病。死生之要会也。脾者。中州也。其平和不可得见。衰乃见耳。来如雀之啄。如水之下漏。是脾衰之见也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5yyBy10WdTF', 1, '{"title":"十六难","description":"<p>1、曰。脉有三部九候。有阴阳。有轻重。有六十首。一脉变为四时。离圣久远。各自是其法。何以别之。然。是其病。有内外证。</p><p>2、其病为之奈何。然。假令得肝脉。其外证。善洁。面青。善怒。其内证。脐左有动气。按之牢若痛。其病。四肢满。闭淋$l{一作癃}。溲便难。转筋。有是者肝也。无是者非也。</p><p>3、假令得心脉。其外证。面赤。口干。喜笑。其内证。脐上有动气。按之牢若痛。其病。烦心。心痛。掌中热而啘。有是者心也。无是者非也。</p><p>4、假令得脾脉。其外证。面黄。善噫。善思。善味。其内证。当脐有动气。按之牢若痛。其病。腹胀满。食不消。体重节痛。怠惰嗜卧。四肢不收。有是者脾也。无是者非也。</p><p>5、假令得肺脉。其外证。面白。善嚏。悲愁不乐。欲哭。其内证。脐右有动气。按之牢若痛。其病。喘咳。洒淅寒热。有是者肺也。无是者非也。</p><p>6、假令得肾脉。其外证。面黑。善恐欠。其内证。脐下有动气。按之牢若痛。其病。逆气。小腹急痛。泄如下重。足胫寒而逆。有是者肾也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100016}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有三部九候。有阴阳。有轻重。有六十首。一脉变为四时。离圣久远。各自是其法。何以别之。然。是其病。有内外证。 2、其病为之奈何。然。假令得肝脉。其外证。善洁。面青。善怒。其内证。脐左有动气。按之牢若痛。其病。四肢满。闭淋$l{一作癃}。溲便难。转筋。有是者肝也。无是者非也。 3、假令得心脉。其外证。面赤。口干。喜笑。其内证。脐上有动气。按之牢若痛。其病。烦心。心痛。掌中热而啘。有是者心也。无是者非也。 4、假令得脾脉。其外证。面黄。善噫。善思。善味。其内证。当脐有动气。按之牢若痛。其病。腹胀满。食不消。体重节痛。怠惰嗜卧。四肢不收。有是者脾也。无是者非也。 5、假令得肺脉。其外证。面白。善嚏。悲愁不乐。欲哭。其内证。脐右有动气。按之牢若痛。其病。喘咳。洒淅寒热。有是者肺也。无是者非也。 6、假令得肾脉。其外证。面黑。善恐欠。其内证。脐下有动气。按之牢若痛。其病。逆气。小腹急痛。泄如下重。足胫寒而逆。有是者肾也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I2r9Elg0dXT', 1, '{"title":"十七难","description":"<p>1、曰。经言病或有死。或有不治自愈。或连年月不已。其死生存亡。可切脉而知之耶。然。可尽知也。</p><p>2、诊病若闭目不欲见人者。脉当得肝脉强急而长。反得肺脉浮短而涩者。死也。</p><p>3、病若开目而渴。心下牢者。脉当得紧实而数。而反得沉涩而微者。死也。</p><p>4、病若吐血。复鼽衄血者。脉当沉细。而反浮大而牢者。死也。</p><p>5、病若谵言妄语。身当有热。脉当洪大。而反手足厥逆。脉沉细而微者。死也。</p><p>6、病若大腹而泄者。脉当微细而涩。反紧大而滑者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100017}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言病或有死。或有不治自愈。或连年月不已。其死生存亡。可切脉而知之耶。然。可尽知也。 2、诊病若闭目不欲见人者。脉当得肝脉强急而长。反得肺脉浮短而涩者。死也。 3、病若开目而渴。心下牢者。脉当得紧实而数。而反得沉涩而微者。死也。 4、病若吐血。复鼽衄血者。脉当沉细。而反浮大而牢者。死也。 5、病若谵言妄语。身当有热。脉当洪大。而反手足厥逆。脉沉细而微者。死也。 6、病若大腹而泄者。脉当微细而涩。反紧大而滑者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V2iJpMQx1iW', 1, '{"title":"十八难","description":"<p>1、曰。脉有三部。部有四经。手有太阴。阳明。足有太阳。少阴。为上下部。何谓也。</p><p>2、然。手太阴。阳明金也。足少阴。太阳水也。金生水。水流下行而不能上。故在下部也。</p><p>3、足厥阴。少阳木也。生手太阳。少阴火。火炎上行而不能下。故为上部。</p><p>4、手心主。少阳火。生足太阴。阳明土。土主中宫。故在中部也。</p><p>5、此皆五行子母更相生养者也。</p><p>6、脉有三部九侯。各何主之。然。三部者。寸。关。尺也。九侯者。浮。中。沉也。</p><p>7、上部法天。主胸上至头之有疾也。中部法人。主鬲以下至脐之有疾也。下部法地。主脐以下至足之有疾也。审而刺之者也。</p><p>8、人病有沉滞久积聚。可切脉而知之耶。然。诊病在右胁有积气。得肺脉。结脉。结甚则积甚。结微则气微。</p><p>9、诊不得肺脉。而右胁有积气者。何也。然。肺脉虽不见。右手脉当沉伏。</p><p>10、其外痼疾同法耶。将异也。然。结者。脉来去时一止。无常数。名曰结也。伏者。脉行筋下也。浮者。脉在肉上行也。左右表里。法皆如此。假令脉结伏者。内无积聚。脉浮结者。外无痼疾。有积聚脉不结伏。有痼疾脉不浮结。为脉不应病。病不应脉。是为死病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100018}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有三部。部有四经。手有太阴。阳明。足有太阳。少阴。为上下部。何谓也。 2、然。手太阴。阳明金也。足少阴。太阳水也。金生水。水流下行而不能上。故在下部也。 3、足厥阴。少阳木也。生手太阳。少阴火。火炎上行而不能下。故为上部。 4、手心主。少阳火。生足太阴。阳明土。土主中宫。故在中部也。 5、此皆五行子母更相生养者也。 6、脉有三部九侯。各何主之。然。三部者。寸。关。尺也。九侯者。浮。中。沉也。 7、上部法天。主胸上至头之有疾也。中部法人。主鬲以下至脐之有疾也。下部法地。主脐以下至足之有疾也。审而刺之者也。 8、人病有沉滞久积聚。可切脉而知之耶。然。诊病在右胁有积气。得肺脉。结脉。结甚则积甚。结微则气微。 9、诊不得肺脉。而右胁有积气者。何也。然。肺脉虽不见。右手脉当沉伏。 10、其外痼疾同法耶。将异也。然。结者。脉来去时一止。无常数。名曰结也。伏者。脉行筋下也。浮者。脉在肉上行也。左右表里。法皆如此。假令脉结伏者。内无积聚。脉浮结者。外无痼疾。有积聚脉不结伏。有痼疾脉不浮结。为脉不应病。病不应脉。是为死病也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x6sVaQMToeB', 1, '{"title":"十九难","description":"<p>1、曰。经言脉有逆顺。男女有恒$l{一本作常}。而反者。何谓也。然。男子生于寅。寅为木。阳也。女子生于申。申为金。阴也。故男脉在关上。女脉在关下。是以男子尺脉恒弱。女子尺脉恒盛。是其常也。反者。男得女脉。女得男脉也。</p><p>2、其为病何如。然。男得女脉为不足。病在内。左得之。病在左。右得之。病在右。随脉言之也。女得男脉为太过。病在四肢。左得之。病在左。右得之。病在右。随脉言之。此之渭也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100019}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言脉有逆顺。男女有恒$l{一本作常}。而反者。何谓也。然。男子生于寅。寅为木。阳也。女子生于申。申为金。阴也。故男脉在关上。女脉在关下。是以男子尺脉恒弱。女子尺脉恒盛。是其常也。反者。男得女脉。女得男脉也。 2、其为病何如。然。男得女脉为不足。病在内。左得之。病在左。右得之。病在右。随脉言之也。女得男脉为太过。病在四肢。左得之。病在左。右得之。病在右。随脉言之。此之渭也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nsfSw4vZF81', 1, '{"title":"二十难","description":"<p>1、曰。经言脉有伏匿。伏匿于何脏而言伏匿耶。然。谓阴阳更相乘更相伏也。脉居阴部而反阳脉见者。为阳乘阴也。虽阳脉时沉涩而短。此谓阳中伏阴也。脉居阳部而反阴脉见者。为阴乘阳也。虽阳脉时浮滑而长。此谓阴中伏阳也。重阳者狂。重阴者癫。脱阳者。见鬼。脱阴者。目盲。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100020}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言脉有伏匿。伏匿于何脏而言伏匿耶。然。谓阴阳更相乘更相伏也。脉居阴部而反阳脉见者。为阳乘阴也。虽阳脉时沉涩而短。此谓阳中伏阴也。脉居阳部而反阴脉见者。为阴乘阳也。虽阳脉时浮滑而长。此谓阴中伏阳也。重阳者狂。重阴者癫。脱阳者。见鬼。脱阴者。目盲。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('quW0IlRMAIV', 1, '{"title":"二十一难","description":"<p>1、曰。经言人形病。脉不病。曰生。脉病。形不病。曰死。何谓也。然。人形病。脉不病。非有不病者也。谓息数不应脉数也。此大法。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100021}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言人形病。脉不病。曰生。脉病。形不病。曰死。何谓也。然。人形病。脉不病。非有不病者也。谓息数不应脉数也。此大法。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XIB4JKp03LC', 1, '{"title":"二十二难","description":"<p>1、曰。经言脉有是动。有所生病。一脉辄$l{一本无辄字}变为二病者。何也。然。经言是动者。气也。所生病者。血也。邪在气。气为是动。邪在血。血为所生病。气主呴之。血主濡之。气留而不行者。为气先病也。血壅而不濡者。为血后病也。故先为是动。后所生$l{一本有病字}也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100022}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言脉有是动。有所生病。一脉辄$l{一本无辄字}变为二病者。何也。然。经言是动者。气也。所生病者。血也。邪在气。气为是动。邪在血。血为所生病。气主呴之。血主濡之。气留而不行者。为气先病也。血壅而不濡者。为血后病也。故先为是动。后所生$l{一本有病字}也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VMPVY1EzaYV', 1, '{"title":"二十三难","description":"<p>1、曰。手足三阴三阳。脉之度数。可晓以不。然。手三阳之脉。从手至头。长五尺。五六合三丈。手三阴之脉。从手至胸中。长三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足三阳之脉。从足至头。长八尺。六八四丈八尺。足三阴之脉。从足至胸。长六尺五寸。六六三丈六尺。五六三尺。合三丈九尺。人两足跷脉。从足至目。长七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各长四尺五寸。二四八尺。二五一尺。合九尺。凡脉长一十六丈二尺。此所谓经脉长短之数也。</p><p>2、经脉十二。络脉十五。何始何穷也。然。经脉者。行血气。通阴阳。以荣于身者也。其始从中焦。注手太阴。阳明。阳明注足阳明。太阴。太阴注手少阴。太阳。太阳注足太阳。少阴。少阴注手心主。少阳。少阳注足少阳。厥阴。厥阴复还注手太阴。别络十五。皆因其原。如环无端。转相灌溉。朝于寸口。人迎。以处百病。而决死生也。</p><p>3、经云。明知始终。阴阳定矣。何谓也。然。终始者。脉之纪也。寸口。人迎。阴阳之气通于朝使。如环无端。故曰始也。终者。三阴三阳之脉绝。绝则死。死各有形。故曰终也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100023}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。手足三阴三阳。脉之度数。可晓以不。然。手三阳之脉。从手至头。长五尺。五六合三丈。手三阴之脉。从手至胸中。长三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足三阳之脉。从足至头。长八尺。六八四丈八尺。足三阴之脉。从足至胸。长六尺五寸。六六三丈六尺。五六三尺。合三丈九尺。人两足跷脉。从足至目。长七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各长四尺五寸。二四八尺。二五一尺。合九尺。凡脉长一十六丈二尺。此所谓经脉长短之数也。 2、经脉十二。络脉十五。何始何穷也。然。经脉者。行血气。通阴阳。以荣于身者也。其始从中焦。注手太阴。阳明。阳明注足阳明。太阴。太阴注手少阴。太阳。太阳注足太阳。少阴。少阴注手心主。少阳。少阳注足少阳。厥阴。厥阴复还注手太阴。别络十五。皆因其原。如环无端。转相灌溉。朝于寸口。人迎。以处百病。而决死生也。 3、经云。明知始终。阴阳定矣。何谓也。然。终始者。脉之纪也。寸口。人迎。阴阳之气通于朝使。如环无端。故曰始也。终者。三阴三阳之脉绝。绝则死。死各有形。故曰终也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bGPZEXjn6pa', 1, '{"title":"二十四难","description":"<p>1、曰。手足三阴三阳气已绝。何以为候。可知其吉凶不。然。足少阴气绝。则骨枯。少阴者。冬脉也。伏行而濡于骨髓。故骨髓不濡。即肉不着骨。骨肉不相亲。即肉濡而却。肉濡而却。故齿长而枯。发无润泽。无润泽者。骨先死。戊日笃。己日死。</p><p>2、足太阴气绝。则脉不营其口唇。口唇者。肌肉之本也。脉不营。则肌肉不滑泽。肌肉不滑泽。则人中满。人中满。则唇反。唇反。则肉先死。甲日笃。乙日死。</p><p>3、足厥阴气绝。即筋缩引卵与舌卷。厥阴者。肝脉也。肝者。筋之合也。筋者。聚于阴器而络于舌本。故脉不营。则筋缩急。即引卵与舌。故舌卷卵缩。此筋先死。庚日笃。辛日死。</p><p>4、手太阴气绝。即皮毛焦。太阴者。肺也。行气温于皮毛者也。气弗营。则皮毛焦。皮毛焦。则津液去。津液去。则皮节伤。皮节伤。则皮枯毛折。毛折者。则毛先死。丙日笃。丁日死。</p><p>5、手少阴气绝。则脉不通。脉不通。则血不流。血不流。则色泽去。故面色黑如黧。此血先死。壬日笃。癸日死。</p><p>6、三阴气俱绝者。则目眩转。目瞑。目瞑者。为失志。失志者。则志先死。死即$l{一本作则}目瞑也。</p><p>7、六阳气俱绝者。则阴与阳相离。阴阳相离。则腠理泄。绝汗乃出。大如贯珠。转出不流。即气先死。旦占夕死。夕占旦死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100024}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。手足三阴三阳气已绝。何以为候。可知其吉凶不。然。足少阴气绝。则骨枯。少阴者。冬脉也。伏行而濡于骨髓。故骨髓不濡。即肉不着骨。骨肉不相亲。即肉濡而却。肉濡而却。故齿长而枯。发无润泽。无润泽者。骨先死。戊日笃。己日死。 2、足太阴气绝。则脉不营其口唇。口唇者。肌肉之本也。脉不营。则肌肉不滑泽。肌肉不滑泽。则人中满。人中满。则唇反。唇反。则肉先死。甲日笃。乙日死。 3、足厥阴气绝。即筋缩引卵与舌卷。厥阴者。肝脉也。肝者。筋之合也。筋者。聚于阴器而络于舌本。故脉不营。则筋缩急。即引卵与舌。故舌卷卵缩。此筋先死。庚日笃。辛日死。 4、手太阴气绝。即皮毛焦。太阴者。肺也。行气温于皮毛者也。气弗营。则皮毛焦。皮毛焦。则津液去。津液去。则皮节伤。皮节伤。则皮枯毛折。毛折者。则毛先死。丙日笃。丁日死。 5、手少阴气绝。则脉不通。脉不通。则血不流。血不流。则色泽去。故面色黑如黧。此血先死。壬日笃。癸日死。 6、三阴气俱绝者。则目眩转。目瞑。目瞑者。为失志。失志者。则志先死。死即$l{一本作则}目瞑也。 7、六阳气俱绝者。则阴与阳相离。阴阳相离。则腠理泄。绝汗乃出。大如贯珠。转出不流。即气先死。旦占夕死。夕占旦死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6LIiawVrQfT', 1, '{"title":"二十五难","description":"<p>1、曰。有十二经。五脏六腑十一耳。其一经者。何等经也。然。一经者。手少阴与心主别脉也。心主与三焦为表里。俱有名而无形。故言经有十二也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100025}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。有十二经。五脏六腑十一耳。其一经者。何等经也。然。一经者。手少阴与心主别脉也。心主与三焦为表里。俱有名而无形。故言经有十二也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eezbSxnIJv9', 1, '{"title":"二十六难","description":"<p>1、曰。经有十二。络有十五。余三络者。是何等络也。然。有阳络。有阴络。有脾之大络。阳络者。阳跷之络也。阴络者。阴跷之络也。故络有十五焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100026}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经有十二。络有十五。余三络者。是何等络也。然。有阳络。有阴络。有脾之大络。阳络者。阳跷之络也。阴络者。阴跷之络也。故络有十五焉。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aTMz8jofExQ', 1, '{"title":"二十七难","description":"<p>1、曰。脉有奇经八脉者。不拘于十二经。何也。然。有阳维。有阴维。有阳跷。有阴跷。有冲。有督。有任。有带之脉。凡此八脉者。皆不拘于经。故曰奇经八脉也。</p><p>2、经有十二。络有十五。凡二十七。气相随上下。何独不拘于经也。然。圣人图设沟渠。通利水道。以备不虞。天雨降下。沟渠溢满。当此之时。留需妄行。圣人不能复图也。此络脉满溢。诸经不能复拘也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100027}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。脉有奇经八脉者。不拘于十二经。何也。然。有阳维。有阴维。有阳跷。有阴跷。有冲。有督。有任。有带之脉。凡此八脉者。皆不拘于经。故曰奇经八脉也。 2、经有十二。络有十五。凡二十七。气相随上下。何独不拘于经也。然。圣人图设沟渠。通利水道。以备不虞。天雨降下。沟渠溢满。当此之时。留需妄行。圣人不能复图也。此络脉满溢。诸经不能复拘也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uMrlcTQ2VEC', 1, '{"title":"二十八难","description":"<p>1、曰。其奇经八脉者。既不拘于十二经。皆何起何继也。然。督脉者。起于下极之俞。并于脊里。上至风府。入属于脑。</p><p>2、任脉者。起于中极之下。以上毛际。循腹里。上关元。至咽喉。</p><p>3、冲脉者。起于气冲。并足阳明之经。夹脐上行。至胸中而散也。</p><p>4、带脉者。起于季胁。回身一周。阳跷脉者。起于跟中。循外踝上行。入风池。</p><p>5、阴跷脉者。亦起于跟中。循内踝上行。至咽喉。交贯冲脉。</p><p>6、阳维。阴维者。维络于身。溢蓄。不能环流灌溉诸经者也。故阳维起于诸阳会也。阴维起于诸阴交也。</p><p>7、比于圣人图设沟渠。沟渠满溢。流于深湖。故圣人不能拘通也。而人脉隆盛。入于八脉。而不还周。故十二经亦有不能拘之。其受邪气。畜则肿热。砭射之也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100028}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。其奇经八脉者。既不拘于十二经。皆何起何继也。然。督脉者。起于下极之俞。并于脊里。上至风府。入属于脑。 2、任脉者。起于中极之下。以上毛际。循腹里。上关元。至咽喉。 3、冲脉者。起于气冲。并足阳明之经。夹脐上行。至胸中而散也。 4、带脉者。起于季胁。回身一周。阳跷脉者。起于跟中。循外踝上行。入风池。 5、阴跷脉者。亦起于跟中。循内踝上行。至咽喉。交贯冲脉。 6、阳维。阴维者。维络于身。溢蓄。不能环流灌溉诸经者也。故阳维起于诸阳会也。阴维起于诸阴交也。 7、比于圣人图设沟渠。沟渠满溢。流于深湖。故圣人不能拘通也。而人脉隆盛。入于八脉。而不还周。故十二经亦有不能拘之。其受邪气。畜则肿热。砭射之也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zaVSlZl8BHq', 1, '{"title":"二十九难","description":"<p>1、曰。奇经之为病。何如。然。阳维维于阳。阴维维于阴。阴阳不能自相维。则怅然失志。溶溶不能自收持。</p><p>2、阳维为病苦寒热。阴维为病若心痛。</p><p>3、阴跷为病。阳缓而阴急。阳跷为病。阴缓而阳急。</p><p>4、冲之为病。逆气而里急。</p><p>5、督之为病。脊强而厥。</p><p>6、任之为病。其内苦结。男子为七疝。妇子为瘕聚。带之为病。腹满。腰溶溶若坐水中。此奇经八脉之为病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100029}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。奇经之为病。何如。然。阳维维于阳。阴维维于阴。阴阳不能自相维。则怅然失志。溶溶不能自收持。 2、阳维为病苦寒热。阴维为病若心痛。 3、阴跷为病。阳缓而阴急。阳跷为病。阴缓而阳急。 4、冲之为病。逆气而里急。 5、督之为病。脊强而厥。 6、任之为病。其内苦结。男子为七疝。妇子为瘕聚。带之为病。腹满。腰溶溶若坐水中。此奇经八脉之为病也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lr26ABcpIfP', 1, '{"title":"三十难","description":"<p>1、曰。营气之行。常与卫气相随不。然。经言人受气于谷。谷入于胃。乃传于五脏六腑。五脏六腑皆受于气。其清者为营。浊者为卫。荣行脉中。卫行脉外。营周不息。五十而复大会。阴阳相贯。如环之无端。故知营卫相随也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100030}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。营气之行。常与卫气相随不。然。经言人受气于谷。谷入于胃。乃传于五脏六腑。五脏六腑皆受于气。其清者为营。浊者为卫。荣行脉中。卫行脉外。营周不息。五十而复大会。阴阳相贯。如环之无端。故知营卫相随也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cz2SzBVizNw', 1, '{"title":"三十一难","description":"<p>1、曰。三焦者。何禀何生。何始何终。其治常在何许。可晓以不。然。三焦者。水谷之道路。气之所终始也。</p><p>2、上焦者。在心下。下膈。在胃上口。主内而不出。其治在膻中。玉堂下一寸六分。直两乳间陷者是。</p><p>3、中焦者。在胃中脘。不上不下。主腐熟水谷。其治在脐傍。</p><p>4、下焦者。当膀胱上口。主分别清浊。主出而不内。以传导也。其治在脐下一寸。故名曰三焦。其府在气街。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100031}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。三焦者。何禀何生。何始何终。其治常在何许。可晓以不。然。三焦者。水谷之道路。气之所终始也。 2、上焦者。在心下。下膈。在胃上口。主内而不出。其治在膻中。玉堂下一寸六分。直两乳间陷者是。 3、中焦者。在胃中脘。不上不下。主腐熟水谷。其治在脐傍。 4、下焦者。当膀胱上口。主分别清浊。主出而不内。以传导也。其治在脐下一寸。故名曰三焦。其府在气街。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jk6imqoa25A', 1, '{"title":"三十二难","description":"<p>1、曰。五脏俱等。而心肺独在鬲上者。何也。然。心者血。肺者气。血为荣。气为卫。相随上下。谓之荣卫。通行经络。营周于外。故令心肺独在鬲上也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100032}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏俱等。而心肺独在鬲上者。何也。然。心者血。肺者气。血为荣。气为卫。相随上下。谓之荣卫。通行经络。营周于外。故令心肺独在鬲上也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hmTJWk4UeKC', 1, '{"title":"三十三难","description":"<p>1、曰。肝青象木。肺白象金。肝得水而沉。木得水而浮。肺得水而浮。金得水而沉。其意何也。然。肝者。非为纯木也。乙角也。庚之柔。大言阴与阳。小言夫与妇。释其微阳。而吸其微阴之气。其意乐金。又行阴道多。故令肝得水而沉也。肺者。非为纯金也。辛商也。丙之柔。大言阴与阳。小言夫与妇。释其微阴。婚而就火。其意乐火。又行阳道多。故令肺得水而浮也。肺熟而复沉。肝熟而复浮者。何也。故知辛当归庚。乙当归甲也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100033}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。肝青象木。肺白象金。肝得水而沉。木得水而浮。肺得水而浮。金得水而沉。其意何也。然。肝者。非为纯木也。乙角也。庚之柔。大言阴与阳。小言夫与妇。释其微阳。而吸其微阴之气。其意乐金。又行阴道多。故令肝得水而沉也。肺者。非为纯金也。辛商也。丙之柔。大言阴与阳。小言夫与妇。释其微阴。婚而就火。其意乐火。又行阳道多。故令肺得水而浮也。肺熟而复沉。肝熟而复浮者。何也。故知辛当归庚。乙当归甲也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Awk3SX2JsDZ', 1, '{"title":"三十四难","description":"<p>1、曰。五脏各有声。色。臭。味。液。皆可晓知以不。然。《十变》言。肝色青。其臭臊。其味酸。其声呼。其液泣。心色赤。其臭焦。其味苦。其声言。其液汗。脾色黄。其臭香。其味甘。其声歌。其液涎。肺色白。其臭腥。其味辛。其声哭。其液涕。肾色黑。其臭腐。其味咸。其声呻。其液唾。是五脏声。色。臭。味。液也。</p><p>2、五脏有七神。各何所藏那。然。脏者。人之神气所舍藏也。故肝藏魂。肺藏魄。心藏神。脾藏意与智。肾藏精与志也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100034}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏各有声。色。臭。味。液。皆可晓知以不。然。《十变》言。肝色青。其臭臊。其味酸。其声呼。其液泣。心色赤。其臭焦。其味苦。其声言。其液汗。脾色黄。其臭香。其味甘。其声歌。其液涎。肺色白。其臭腥。其味辛。其声哭。其液涕。肾色黑。其臭腐。其味咸。其声呻。其液唾。是五脏声。色。臭。味。液也。 2、五脏有七神。各何所藏那。然。脏者。人之神气所舍藏也。故肝藏魂。肺藏魄。心藏神。脾藏意与智。肾藏精与志也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cuyMHI0sHsn', 1, '{"title":"三十五难","description":"<p>1、曰。五脏各有所腑皆相近。而心。肺独去大肠。小肠远者。何谓$l{一本无谓字}也。然。经言心营。肺卫。通行阳气。故居在上。大肠。小肠。传阴气而下。故居在下。所以相去而远也。又诸腑皆阳也。清净之处。</p><p>2、今大肠。小肠。胃与膀胱。皆受不净。其意何也。然。诸腑者。谓是非也。经言。小肠者。受盛之腑也。大肠者。传泻行道之腑也。胆者。清净之腑也。胃者。水谷之腑也。膀胱者。津液之腑也。一腑犹无两名。故知非也。小肠者。心之腑。大肠者。肺之腑。胆者。肝之腑。胃者。脾之腑。膀胱者。肾之腑。小肠谓赤肠。大肠谓白肠。胆者谓青肠。胃者谓黄肠。膀胱者谓黑肠。下焦之所治也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100035}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏各有所腑皆相近。而心。肺独去大肠。小肠远者。何谓$l{一本无谓字}也。然。经言心营。肺卫。通行阳气。故居在上。大肠。小肠。传阴气而下。故居在下。所以相去而远也。又诸腑皆阳也。清净之处。 2、今大肠。小肠。胃与膀胱。皆受不净。其意何也。然。诸腑者。谓是非也。经言。小肠者。受盛之腑也。大肠者。传泻行道之腑也。胆者。清净之腑也。胃者。水谷之腑也。膀胱者。津液之腑也。一腑犹无两名。故知非也。小肠者。心之腑。大肠者。肺之腑。胆者。肝之腑。胃者。脾之腑。膀胱者。肾之腑。小肠谓赤肠。大肠谓白肠。胆者谓青肠。胃者谓黄肠。膀胱者谓黑肠。下焦之所治也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q0wtzaZhQxF', 1, '{"title":"三十六难","description":"<p>1、曰。脏各有一耳。肾独有两者。何也。然。肾两者。非皆肾也。其左者为肾。右者为命门。命门者。诸神精之所舍。原气之所系也。男子以藏精。女子以系胞。故知肾有一也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100036}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。脏各有一耳。肾独有两者。何也。然。肾两者。非皆肾也。其左者为肾。右者为命门。命门者。诸神精之所舍。原气之所系也。男子以藏精。女子以系胞。故知肾有一也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CcKl1cAMmUl', 1, '{"title":"三十七难","description":"<p>1、曰。五脏之气。于何发起。通于何许。可晓以不。然。五脏者。常内阅于上七窍也。故肺气通于鼻。鼻和则知香臭矣。肝气通于目。目和则知黑白矣。脾气通于口。口和则知谷味矣。心气通于舌。舌和则知五味矣。肾气通于耳。耳和则知五音矣。五脏不和。则七窍不通。六腑不和。则留结为痈。</p><p>2、邪在六腑。则阳脉不和。阳脉不和。则气留之。气留之。则阳脉盛矣。</p><p>3、邪在五腑。则阴脉不和。阴脉不和。则血留之。血留之。则阴脉盛矣。阴气太盛。则阳气不得相营也。故曰格。阳气太盛。则阴气不得相营也。故曰关。阴阳俱盛。不得相营也。故曰关格。关格者。不得尽其命而死矣。</p><p>4、经言气独行于五脏。不营于六腑者。何也。然。夫气之所行也。如水之流。不得息也。故阴脉营于五脏。阳脉营于六腑。如环无端。莫知其纪。终而复始。其不覆溢。人气内温于脏腑。外濡于凑理。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100037}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏之气。于何发起。通于何许。可晓以不。然。五脏者。常内阅于上七窍也。故肺气通于鼻。鼻和则知香臭矣。肝气通于目。目和则知黑白矣。脾气通于口。口和则知谷味矣。心气通于舌。舌和则知五味矣。肾气通于耳。耳和则知五音矣。五脏不和。则七窍不通。六腑不和。则留结为痈。 2、邪在六腑。则阳脉不和。阳脉不和。则气留之。气留之。则阳脉盛矣。 3、邪在五腑。则阴脉不和。阴脉不和。则血留之。血留之。则阴脉盛矣。阴气太盛。则阳气不得相营也。故曰格。阳气太盛。则阴气不得相营也。故曰关。阴阳俱盛。不得相营也。故曰关格。关格者。不得尽其命而死矣。 4、经言气独行于五脏。不营于六腑者。何也。然。夫气之所行也。如水之流。不得息也。故阴脉营于五脏。阳脉营于六腑。如环无端。莫知其纪。终而复始。其不覆溢。人气内温于脏腑。外濡于凑理。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K9dbKTLq4nt', 1, '{"title":"三十八难","description":"<p>1、曰。脏唯有五。腑独有六者。何也。然。所以腑有六者。谓三焦也。有原气之别焉。主持诸气。有名而无形。其经$l{一本无经字}属手少阳。此外腑也。故言腑有六焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100038}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。脏唯有五。腑独有六者。何也。然。所以腑有六者。谓三焦也。有原气之别焉。主持诸气。有名而无形。其经$l{一本无经字}属手少阳。此外腑也。故言腑有六焉。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Lx1ncampL0', 1, '{"title":"三十九难","description":"<p>1、曰。经言腑有五。脏有六者。何也。然。六腑者。正有五腑也。五脏亦有六脏者。谓肾有两脏也。其左为肾。右为命门。命门者。谓精神之所舍也。男子以藏精。女子以系胞。其气与肾通。故言脏有六也。</p><p>2、腑有五者。何也。然。五脏各一腑。三焦亦是一腑。然不属于五脏。故言腑有五焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100039}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。经言腑有五。脏有六者。何也。然。六腑者。正有五腑也。五脏亦有六脏者。谓肾有两脏也。其左为肾。右为命门。命门者。谓精神之所舍也。男子以藏精。女子以系胞。其气与肾通。故言脏有六也。 2、腑有五者。何也。然。五脏各一腑。三焦亦是一腑。然不属于五脏。故言腑有五焉。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ek2BOybp1AR', 1, '{"title":"四十难","description":"<p>1、曰。经言。肝主色。心主臭。脾主味。肺主声。肾主液。鼻者。肺之候。而反知香臭。耳者。肾之候。而反闻声。其意何也。然。肺者。西方金也。金生于巳。巳者南方火。火者心。心主臭。故令鼻知香臭。肾者。北方水也。水生于申。申者西方金。金者肺。肺主声。故令耳闻声。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100040}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。经言。肝主色。心主臭。脾主味。肺主声。肾主液。鼻者。肺之候。而反知香臭。耳者。肾之候。而反闻声。其意何也。然。肺者。西方金也。金生于巳。巳者南方火。火者心。心主臭。故令鼻知香臭。肾者。北方水也。水生于申。申者西方金。金者肺。肺主声。故令耳闻声。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3cOAMkyhkdK', 1, '{"title":"四十一难","description":"<p>1、曰。肝独有两叶。以何应也。然。肝者。东方木也。木者。春也。万物始生。其尚幼小。意无所亲。去太阴尚近。离太阳不远。犹有两心。故有两叶。亦应木叶也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100041}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。肝独有两叶。以何应也。然。肝者。东方木也。木者。春也。万物始生。其尚幼小。意无所亲。去太阴尚近。离太阳不远。犹有两心。故有两叶。亦应木叶也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LZ6KJ3sAjv4', 1, '{"title":"四十二难","description":"<p>1、曰。人肠胃长短。受水谷多少。各几何。然。胃大一尺五寸。径五寸。长二尺六寸。横屈。受水谷三斗五升。其中常留谷二斗。水一斗五升。小肠大二寸半。径八分。分之少半。长三丈二尺。受谷二斗四升。水六升三合。合之大半。回肠大四寸。径一寸半。长二丈一尺。受谷一斗。水七升半。广肠大八寸。径二寸半。长二尺八寸。受谷九升三合。八分合之一。故肠胃凡长五丈八尺四寸。合受水谷八斗七升六合。八分合之一。此肠胃长短。受水谷之数也。肝重四斤四两。左三叶。右四叶。凡七叶。主藏魂。心重十二两。中有七孔三毛。盛精汁三合。主藏神。脾重二斤三两。扁广三寸。长五寸。有散膏半斤。主裹血。温五脏。主藏意。肺重三斤三两。六叶两耳。凡八叶。主藏魄。肾有两枚。重一斤一两。主藏志。胆在肝之短叶间。重三两三铢。盛精汁三合。胃重二斤一两$l{一本作二斤二两，《史记正义》作二斤十四两，多本从此}。纡曲屈伸。长二尺六寸。大一尺五寸。径五寸。盛谷二斗。水一斗五升。小肠重二斤十四两。长三丈二尺。广二寸半。径八分。分之少半。左回叠积十六曲。盛谷二斗四升。水六升三合。合之大半。大肠重二斤十二两。长二丈一尺。广四寸。径一寸。当脐右回十六曲。盛谷一斗。水七升半。膀胱重九两二铢。纵广九寸。盛溺九升九合。口广二寸半。唇至齿长九分。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十二两$l{《灵枢·肠胃》：咽门重十两，多本从之}。广二寸半。至胃长一尺六寸。喉咙重十二两。广二寸。长一尺二寸。九节。肛门重十二两。大八寸。径二寸大半。长二尺八寸。受谷九升三合。八分合之一。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100042}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人肠胃长短。受水谷多少。各几何。然。胃大一尺五寸。径五寸。长二尺六寸。横屈。受水谷三斗五升。其中常留谷二斗。水一斗五升。小肠大二寸半。径八分。分之少半。长三丈二尺。受谷二斗四升。水六升三合。合之大半。回肠大四寸。径一寸半。长二丈一尺。受谷一斗。水七升半。广肠大八寸。径二寸半。长二尺八寸。受谷九升三合。八分合之一。故肠胃凡长五丈八尺四寸。合受水谷八斗七升六合。八分合之一。此肠胃长短。受水谷之数也。肝重四斤四两。左三叶。右四叶。凡七叶。主藏魂。心重十二两。中有七孔三毛。盛精汁三合。主藏神。脾重二斤三两。扁广三寸。长五寸。有散膏半斤。主裹血。温五脏。主藏意。肺重三斤三两。六叶两耳。凡八叶。主藏魄。肾有两枚。重一斤一两。主藏志。胆在肝之短叶间。重三两三铢。盛精汁三合。胃重二斤一两$l{一本作二斤二两，《史记正义》作二斤十四两，多本从此}。纡曲屈伸。长二尺六寸。大一尺五寸。径五寸。盛谷二斗。水一斗五升。小肠重二斤十四两。长三丈二尺。广二寸半。径八分。分之少半。左回叠积十六曲。盛谷二斗四升。水六升三合。合之大半。大肠重二斤十二两。长二丈一尺。广四寸。径一寸。当脐右回十六曲。盛谷一斗。水七升半。膀胱重九两二铢。纵广九寸。盛溺九升九合。口广二寸半。唇至齿长九分。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十二两$l{《灵枢·肠胃》：咽门重十两，多本从之}。广二寸半。至胃长一尺六寸。喉咙重十二两。广二寸。长一尺二寸。九节。肛门重十二两。大八寸。径二寸大半。长二尺八寸。受谷九升三合。八分合之一。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MJOf7WN16tu', 1, '{"title":"四十三难","description":"<p>1、曰。人不食饮。七日而死者。何也。然。人胃中当留谷二斗。水一斗五升。故平人日再至圊。一行二升半。一日中五升。七日五七三斗五升。而水谷尽矣。故平人不食饮七日而死者。水谷津液俱尽。即死矣。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100043}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人不食饮。七日而死者。何也。然。人胃中当留谷二斗。水一斗五升。故平人日再至圊。一行二升半。一日中五升。七日五七三斗五升。而水谷尽矣。故平人不食饮七日而死者。水谷津液俱尽。即死矣。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VDcKULw3sFC', 1, '{"title":"四十四难","description":"<p>1、曰。七冲门何在。然。唇为飞门。齿为户门。会厌为吸门。胃为贲门。太仓下口为幽门。大肠小肠会为阑门。下极为魄门。故曰七冲门也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100044}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。七冲门何在。然。唇为飞门。齿为户门。会厌为吸门。胃为贲门。太仓下口为幽门。大肠小肠会为阑门。下极为魄门。故曰七冲门也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q055Qp9ZT8u', 1, '{"title":"四十五难","description":"<p>1、曰。经言八会者。何也。然。腑会太仓。脏会季胁。筋会阳陵泉。髓会绝骨。血会鬲俞。骨会大抒。脉会太渊。气会三焦外。一筋直两乳内也。热病在内者。取其会之气穴也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100045}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。经言八会者。何也。然。腑会太仓。脏会季胁。筋会阳陵泉。髓会绝骨。血会鬲俞。骨会大抒。脉会太渊。气会三焦外。一筋直两乳内也。热病在内者。取其会之气穴也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4K6bbC3V16i', 1, '{"title":"四十六难","description":"<p>1、曰。老人卧而不寐。少壮寐而不寤者。何也。然。经言少壮者。血气盛。肌肉滑。气道通。营卫之行不失于常。故昼日精。夜不寤也。老人血气衰。肌肉不滑。营卫之道涩。故昼日不能精。夜不得寐也。故知老人不得寐也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100046}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。老人卧而不寐。少壮寐而不寤者。何也。然。经言少壮者。血气盛。肌肉滑。气道通。营卫之行不失于常。故昼日精。夜不寤也。老人血气衰。肌肉不滑。营卫之道涩。故昼日不能精。夜不得寐也。故知老人不得寐也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2swGBP8bcfM', 1, '{"title":"四十七难","description":"<p>1、曰。人面独能耐寒者。何也。然。人头者。诸阳之会也。诸阴脉皆至颈。胸中而还。独诸阳脉皆上至头耳。故令面耐寒也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100047}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人面独能耐寒者。何也。然。人头者。诸阳之会也。诸阴脉皆至颈。胸中而还。独诸阳脉皆上至头耳。故令面耐寒也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ItnpIk9Lezi', 1, '{"title":"四十八难","description":"<p>1、曰。人有三虚三实。何谓也。然。有脉之虚实。有病之虚实。有诊之虚实也。脉之虚实者。濡者为虚。牢者为实。病之虚实者。出者为虚。入者为实。言者为虚。不言者为实。缓者为虚。急者为实。诊之虚实者。痒者为虚。痛者为实。外痛内快。为外实内虚。内痛外快。为内实外虚。故曰虚实也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100048}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人有三虚三实。何谓也。然。有脉之虚实。有病之虚实。有诊之虚实也。脉之虚实者。濡者为虚。牢者为实。病之虚实者。出者为虚。入者为实。言者为虚。不言者为实。缓者为虚。急者为实。诊之虚实者。痒者为虚。痛者为实。外痛内快。为外实内虚。内痛外快。为内实外虚。故曰虚实也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zhTqJFN0qAb', 1, '{"title":"四十九难","description":"<p>1、曰。有正经自病。有五邪所伤。何以别之。然。经言忧愁思虑则伤心。形寒饮冷则伤肺。恚怒气逆。上而不下则伤肝。饮食劳倦则伤脾。久坐湿地。强力入水则伤肾。是正经之自病也。</p><p>2、何谓五邪。然。有中风。有伤暑。有饮食劳倦。有伤寒。有中湿。此之谓五邪。</p><p>3、假令心病。何以知中风得之。然。其色当赤。何以言之。肝主色。自入为青。入心为赤。入脾为黄。入肺为白。入肾为黑。肝为心邪。故知当赤色。其病身热。胁下满痛。其脉浮大而弦。</p><p>4、何以知伤暑得之。然。当恶焦臭。何以言之。心主臭。自入为焦臭。入脾为香臭。入肝为臊臭。入肾为腐臭。入肺为腥臭。故知心病伤暑得之。当恶焦臭。其病身热而烦。心痛。其脉浮大而散。</p><p>5、何以知饮食劳倦得之。然。当喜苦味也。何以言之。脾主味。入肝为酸。人心为苦。入肺为辛。入肾为咸。自入为甘。故知脾邪入心。为喜苦味也。其病身热而体重。嗜卧。四肢不收。其脉浮大而缓。</p><p>6、何以知伤寒得之。然。当谵言妄语。何以言之。肺主声。入肝为呼。入心为言。入脾为歌。入肾为呻。自入为哭。故知肺邪入心。为谵言妄语也。其病身热。洒洒恶寒。甚则喘咳。其脉浮大而涩。</p><p>7、何以知中湿得之。然。当喜汗出不可止。何以言之。肾主液。入肝为泣。入心为汗。入脾为涎。入肺为涕。自入为唾。故知肾邪入心。为汗出不可止也。其病身热。而小腹痛。足胫寒而逆。其脉沉濡而大。此五邪之法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100049}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。有正经自病。有五邪所伤。何以别之。然。经言忧愁思虑则伤心。形寒饮冷则伤肺。恚怒气逆。上而不下则伤肝。饮食劳倦则伤脾。久坐湿地。强力入水则伤肾。是正经之自病也。 2、何谓五邪。然。有中风。有伤暑。有饮食劳倦。有伤寒。有中湿。此之谓五邪。 3、假令心病。何以知中风得之。然。其色当赤。何以言之。肝主色。自入为青。入心为赤。入脾为黄。入肺为白。入肾为黑。肝为心邪。故知当赤色。其病身热。胁下满痛。其脉浮大而弦。 4、何以知伤暑得之。然。当恶焦臭。何以言之。心主臭。自入为焦臭。入脾为香臭。入肝为臊臭。入肾为腐臭。入肺为腥臭。故知心病伤暑得之。当恶焦臭。其病身热而烦。心痛。其脉浮大而散。 5、何以知饮食劳倦得之。然。当喜苦味也。何以言之。脾主味。入肝为酸。人心为苦。入肺为辛。入肾为咸。自入为甘。故知脾邪入心。为喜苦味也。其病身热而体重。嗜卧。四肢不收。其脉浮大而缓。 6、何以知伤寒得之。然。当谵言妄语。何以言之。肺主声。入肝为呼。入心为言。入脾为歌。入肾为呻。自入为哭。故知肺邪入心。为谵言妄语也。其病身热。洒洒恶寒。甚则喘咳。其脉浮大而涩。 7、何以知中湿得之。然。当喜汗出不可止。何以言之。肾主液。入肝为泣。入心为汗。入脾为涎。入肺为涕。自入为唾。故知肾邪入心。为汗出不可止也。其病身热。而小腹痛。足胫寒而逆。其脉沉濡而大。此五邪之法也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('53piW7vYaxn', 1, '{"title":"五十难","description":"<p>1、曰。病有虚邪。有实邪。有贼邪。有微邪。有正邪。何以别之。然。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。何以言之。假令心病。中风得之为虚邪。伤暑得之为正邪。饮食劳倦得之为实邪。伤寒得之为微邪。中湿得之为贼邪。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100050}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。病有虚邪。有实邪。有贼邪。有微邪。有正邪。何以别之。然。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。何以言之。假令心病。中风得之为虚邪。伤暑得之为正邪。饮食劳倦得之为实邪。伤寒得之为微邪。中湿得之为贼邪。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7nDnTOvxTDA', 1, '{"title":"五十一难","description":"<p>1、曰。病有欲得温者。有欲得寒者。有欲得见人者。有不欲得见人者。而各不同。病在何脏腑也。然。病欲得寒。而欲见人者。病在腑也。病欲得温。而不欲见人者。病在脏也。何以言之。腑者阳也。阳病欲得寒。又欲见人。脏者。阴也。阴病欲得温。又欲闭户独处。恶闻人声。故以别知脏腑之病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100051}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。病有欲得温者。有欲得寒者。有欲得见人者。有不欲得见人者。而各不同。病在何脏腑也。然。病欲得寒。而欲见人者。病在腑也。病欲得温。而不欲见人者。病在脏也。何以言之。腑者阳也。阳病欲得寒。又欲见人。脏者。阴也。阴病欲得温。又欲闭户独处。恶闻人声。故以别知脏腑之病也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bmdgqx8u8mn', 1, '{"title":"五十二难","description":"<p>1、曰。脏腑发病。根本等不。然。不等也。其不等奈何。然。脏病者。止而不移。其病不离其处。腑病者。仿佛贲响。上下行流。居处无常。故以此知脏腑根本不同也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100052}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。脏腑发病。根本等不。然。不等也。其不等奈何。然。脏病者。止而不移。其病不离其处。腑病者。仿佛贲响。上下行流。居处无常。故以此知脏腑根本不同也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tnZaX37rA82', 1, '{"title":"五十三难","description":"<p>1、曰。经言七传者死。间脏者生。何谓也。然。七传者。传其所胜也。间脏者。传其子也。何以言之。假令心病传肺。肺传肝。肝传脾。脾传肾。肾传心。一脏不再伤。故言七传者死也。间脏者。传其所生也。假令心病传脾。脾传肺。肺传肾。肾传肝。肝传心。是母子相传。竟而复始。如环无端。故曰生也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100053}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。经言七传者死。间脏者生。何谓也。然。七传者。传其所胜也。间脏者。传其子也。何以言之。假令心病传肺。肺传肝。肝传脾。脾传肾。肾传心。一脏不再伤。故言七传者死也。间脏者。传其所生也。假令心病传脾。脾传肺。肺传肾。肾传肝。肝传心。是母子相传。竟而复始。如环无端。故曰生也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uuLC5t8tL4i', 1, '{"title":"五十四难","description":"<p>1、曰。脏病难治。腑病易治。何谓也。然。脏病所以难治者。传其所胜也。腑病易治者。传其子也。与七传。间传同法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100054}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。脏病难治。腑病易治。何谓也。然。脏病所以难治者。传其所胜也。腑病易治者。传其子也。与七传。间传同法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3X5Y2KxQqIh', 1, '{"title":"五十五难","description":"<p>1、曰。病有积。有聚。何以别之。然。积者。阴气也。聚者。阳气也。故阴沉而伏。阳浮而动。气之所积。名曰积。气之所聚。名曰聚。故积者。五脏所生。聚者。六腑所成也。积者。阴气也。其始发有常处。其痛不离其部。上下有所终始。左右有所穷处。聚者。阳气也。其始发无根本。上下无所留止。其痛无常处谓之聚。故以是别知积聚也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100055}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。病有积。有聚。何以别之。然。积者。阴气也。聚者。阳气也。故阴沉而伏。阳浮而动。气之所积。名曰积。气之所聚。名曰聚。故积者。五脏所生。聚者。六腑所成也。积者。阴气也。其始发有常处。其痛不离其部。上下有所终始。左右有所穷处。聚者。阳气也。其始发无根本。上下无所留止。其痛无常处谓之聚。故以是别知积聚也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4L7cTPlx7JN', 1, '{"title":"五十六难","description":"<p>1、曰。五脏之积。各有名乎。以何月。何日得之。然。肝之积。名曰肥气。在左胁下。如覆杯。有头足。久不愈。令人发咳逆。疟。连岁不已。以季夏戊己日得之。何以言之。肺病传于肝。肝当传脾。脾季夏适王。王者不受邪。肝复欲还肺。肺不肯受。故留结为积。故知肥气以季夏戊己日得之。心之积。名曰伏梁。起脐上。大如臂。上至心下。久不愈。令人病烦心。以秋庚辛日得之。何以言之。肾病传心。心当传肺。肺以秋适王。王者不受邪。心复欲还肾。肾不肯受。故留结为积。故知伏梁以秋庚辛日得之。脾之积。名曰痞气。在胃脘。覆大如盘。久不愈。令人四肢不收。发黄疸。饮食不为肌肤。以冬壬癸日得之。何以言之。肝病传脾。脾当传肾。肾以冬适王。王者不受邪。脾复欲还肝。肝不肯受。故留结为积。故知痞气以冬壬癸日得之。肺之积。名曰息贲。在右胁下。覆大如杯。久不已。令人洒淅寒热。喘咳。发肺壅。以春甲乙日得之。何以言之。心病传肺。肺当传肝。肝以春适王。王者不受邪。肺复欲还心。心不肯受。故留结为积。故知息贲以春甲乙日得之。肾之积。名曰贲豚。发于少腹。上至心下。若豚状。或上或下无时。久不已。令人喘逆。骨痿少气。以夏丙丁日得之。何以言之。脾病传肾。肾当传心。心以夏适王。王者不受邪。肾复欲还脾。脾不肯受。故留结为积。故知贲豚以夏丙丁日得之。此五积之要法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100056}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。五脏之积。各有名乎。以何月。何日得之。然。肝之积。名曰肥气。在左胁下。如覆杯。有头足。久不愈。令人发咳逆。疟。连岁不已。以季夏戊己日得之。何以言之。肺病传于肝。肝当传脾。脾季夏适王。王者不受邪。肝复欲还肺。肺不肯受。故留结为积。故知肥气以季夏戊己日得之。心之积。名曰伏梁。起脐上。大如臂。上至心下。久不愈。令人病烦心。以秋庚辛日得之。何以言之。肾病传心。心当传肺。肺以秋适王。王者不受邪。心复欲还肾。肾不肯受。故留结为积。故知伏梁以秋庚辛日得之。脾之积。名曰痞气。在胃脘。覆大如盘。久不愈。令人四肢不收。发黄疸。饮食不为肌肤。以冬壬癸日得之。何以言之。肝病传脾。脾当传肾。肾以冬适王。王者不受邪。脾复欲还肝。肝不肯受。故留结为积。故知痞气以冬壬癸日得之。肺之积。名曰息贲。在右胁下。覆大如杯。久不已。令人洒淅寒热。喘咳。发肺壅。以春甲乙日得之。何以言之。心病传肺。肺当传肝。肝以春适王。王者不受邪。肺复欲还心。心不肯受。故留结为积。故知息贲以春甲乙日得之。肾之积。名曰贲豚。发于少腹。上至心下。若豚状。或上或下无时。久不已。令人喘逆。骨痿少气。以夏丙丁日得之。何以言之。脾病传肾。肾当传心。心以夏适王。王者不受邪。肾复欲还脾。脾不肯受。故留结为积。故知贲豚以夏丙丁日得之。此五积之要法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5IhW81cQXaL', 1, '{"title":"五十七难","description":"<p>1、曰。泄凡有几。皆有名不。然。泄凡有五。其名不同。有胃泄。有脾泄。有大肠泄。有小肠泄。有大瘕泄。名曰后重。胃泄者。饮食不化。色黄。脾泄者。腹胀满。泄注。食即呕吐逆。大肠泄者。食已窘迫。大便色白。肠鸣切痛。小肠泄者。溲而便脓血。少腹痛。大瘕泄者。里急后重。数至圊而不能便。茎中痛。此五泄之要法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100057}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。泄凡有几。皆有名不。然。泄凡有五。其名不同。有胃泄。有脾泄。有大肠泄。有小肠泄。有大瘕泄。名曰后重。胃泄者。饮食不化。色黄。脾泄者。腹胀满。泄注。食即呕吐逆。大肠泄者。食已窘迫。大便色白。肠鸣切痛。小肠泄者。溲而便脓血。少腹痛。大瘕泄者。里急后重。数至圊而不能便。茎中痛。此五泄之要法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8JUFq9AxEPb', 1, '{"title":"五十八难","description":"<p>1、曰。伤寒有几。其脉有变不。然。伤寒有五。有中风。有伤寒。有湿温。有热病。有温病。其所苦各不同。</p><p>2、中风之脉。阳浮而滑。阴濡而弱。湿温之脉。阳濡而弱。阴小而急。伤寒之脉。阴阳俱盛而紧涩。热病之脉。阴阳俱浮。浮之而滑。沉之散涩。温病之脉。行在诸经。不知何经之动也。各随其经所在而取之。</p><p>3、伤寒有汗出而愈。下之而死者。有汗出而死。下之而愈者。何也。然。阳虚阴盛。汗出而愈。下之即死。阳盛阴虚。汗出而死。下之而愈。</p><p>4、寒热之病。候之如何也。然。皮寒热者。皮不可近席。毛发焦。鼻槁。不得汗。肌寒热者。肌痛。唇舌槁。无汗。骨寒热者。病无所安。汗注不休。齿本槁痛。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100058}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。伤寒有几。其脉有变不。然。伤寒有五。有中风。有伤寒。有湿温。有热病。有温病。其所苦各不同。 2、中风之脉。阳浮而滑。阴濡而弱。湿温之脉。阳濡而弱。阴小而急。伤寒之脉。阴阳俱盛而紧涩。热病之脉。阴阳俱浮。浮之而滑。沉之散涩。温病之脉。行在诸经。不知何经之动也。各随其经所在而取之。 3、伤寒有汗出而愈。下之而死者。有汗出而死。下之而愈者。何也。然。阳虚阴盛。汗出而愈。下之即死。阳盛阴虚。汗出而死。下之而愈。 4、寒热之病。候之如何也。然。皮寒热者。皮不可近席。毛发焦。鼻槁。不得汗。肌寒热者。肌痛。唇舌槁。无汗。骨寒热者。病无所安。汗注不休。齿本槁痛。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9T2reSqxos6', 1, '{"title":"五十九难","description":"<p>1、曰。狂癫之病。何以别之。然。狂疾之始发。少卧而不饥。自高贤也。自辨智也。自贵倨也。妄笑好歌乐。妄行不休是也。癫疾始发。意不乐。僵仆直视。其脉三部阴阳俱盛是也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100059}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。狂癫之病。何以别之。然。狂疾之始发。少卧而不饥。自高贤也。自辨智也。自贵倨也。妄笑好歌乐。妄行不休是也。癫疾始发。意不乐。僵仆直视。其脉三部阴阳俱盛是也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('chFYIEIlE0s', 1, '{"title":"六十难","description":"<p>1、曰。头心之病。有厥痛。有真痛。何谓也。然。手三阳之脉。受风寒。伏留而不去者。则名厥头痛。入连在脑者。名真头痛。其五脏气相干。名厥心痛。其痛甚。但在心。手足青者。即名真心痛。其真心痛者。旦发夕死。夕发旦死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100060}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。头心之病。有厥痛。有真痛。何谓也。然。手三阳之脉。受风寒。伏留而不去者。则名厥头痛。入连在脑者。名真头痛。其五脏气相干。名厥心痛。其痛甚。但在心。手足青者。即名真心痛。其真心痛者。旦发夕死。夕发旦死。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uB71sfbiDy6', 1, '{"title":"六十一难","description":"<p>1、曰。经言。望而知之谓之神。闻而知之谓之圣。问而知之谓之工。切脉而知之谓之巧。何谓也。然。望而知之者。望见其五色。以知其病。闻而知之者。闻其五音。以别其病。问而知之者。问其所欲五味。以知其病所起所在也。切脉而知之者。诊其寸口。视其虚实。以知其病。病在何脏腑也。经言。以外知之曰圣。以内知之曰神。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100061}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。经言。望而知之谓之神。闻而知之谓之圣。问而知之谓之工。切脉而知之谓之巧。何谓也。然。望而知之者。望见其五色。以知其病。闻而知之者。闻其五音。以别其病。问而知之者。问其所欲五味。以知其病所起所在也。切脉而知之者。诊其寸口。视其虚实。以知其病。病在何脏腑也。经言。以外知之曰圣。以内知之曰神。此之谓也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZBsHCPKTnmi', 1, '{"title":"六十二难","description":"<p>1、曰。脏井。荥有五。腑独有六者。何谓也。然。腑者。阳也。三焦行于诸阳。故置一俞。名曰原。腑有六者。亦与三焦共一气也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100062}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。脏井。荥有五。腑独有六者。何谓也。然。腑者。阳也。三焦行于诸阳。故置一俞。名曰原。腑有六者。亦与三焦共一气也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jj9iLd2qY0u', 1, '{"title":"六十三难","description":"<p>1、曰。《十变》言。五脏六腑荥。合。皆以井为始者。何也。然。井者。东方春也。万物之始生。诸蚑行喘息。蚏飞蠕动。当生之物。莫不以春生。故岁数始于春。日数始于甲。故以井为始也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100063}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。《十变》言。五脏六腑荥。合。皆以井为始者。何也。然。井者。东方春也。万物之始生。诸蚑行喘息。蚏飞蠕动。当生之物。莫不以春生。故岁数始于春。日数始于甲。故以井为始也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kIX7rMyolCc', 1, '{"title":"六十四难","description":"<p>1、曰。《十变》又言。阴井木。阳井金。阴荥火。阳荥水。阴俞土。阳俞木。阴经金。阳经火。阴合水。阳合土。阴阳皆不同。其意何也。然。是刚柔之事也。阴井乙木。阳井庚金。阳井庚。庚者。乙之刚也。阴井乙。乙者。庚之柔也。乙为木。故言阴井木也。庚为金。故言阳井金也。余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100064}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。《十变》又言。阴井木。阳井金。阴荥火。阳荥水。阴俞土。阳俞木。阴经金。阳经火。阴合水。阳合土。阴阳皆不同。其意何也。然。是刚柔之事也。阴井乙木。阳井庚金。阳井庚。庚者。乙之刚也。阴井乙。乙者。庚之柔也。乙为木。故言阴井木也。庚为金。故言阳井金也。余皆仿此。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hX5PiDMlon3', 1, '{"title":"六十五难","description":"<p>1、曰。经言。所出为井。所入为合。其法奈何。然。所出为井。井者。东方春也。万物之始生。故言所出为井也。所入为合。合者。北方冬也。阳气入藏。故言所入为合也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100065}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。所出为井。所入为合。其法奈何。然。所出为井。井者。东方春也。万物之始生。故言所出为井也。所入为合。合者。北方冬也。阳气入藏。故言所入为合也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vEs9VOkPv1f', 1, '{"title":"六十六难","description":"<p>1、曰。经言。肺之原。出于太渊。心之原。出于太陵。肝之原。出于太冲。脾之原。出于大白。肾之原。出于太溪。少阴之原。出于兑骨。胆之原。出于丘墟。胃之原。出于冲阳。三焦之原。出于阳池。膀胱之原。出于京骨。大肠之原。出于合谷。小肠之原。出于腕骨。十二经皆以俞为原者。何也。然。五脏俞者。三焦之所行。气之所留止也。</p><p>2、三焦所行之俞为原者。何也。然。脐下肾间动气者。人之生命也。十二经之根本也。故名曰原。三焦者。原气之别使也。主通行三气。经历于五脏六腑。原者。三焦之尊号也。故所止辄为原。五脏六腑之有病者。皆取其原也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100066}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。肺之原。出于太渊。心之原。出于太陵。肝之原。出于太冲。脾之原。出于大白。肾之原。出于太溪。少阴之原。出于兑骨。胆之原。出于丘墟。胃之原。出于冲阳。三焦之原。出于阳池。膀胱之原。出于京骨。大肠之原。出于合谷。小肠之原。出于腕骨。十二经皆以俞为原者。何也。然。五脏俞者。三焦之所行。气之所留止也。 2、三焦所行之俞为原者。何也。然。脐下肾间动气者。人之生命也。十二经之根本也。故名曰原。三焦者。原气之别使也。主通行三气。经历于五脏六腑。原者。三焦之尊号也。故所止辄为原。五脏六腑之有病者。皆取其原也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iN7Ix924znk', 1, '{"title":"六十七难","description":"<p>1、曰。五脏募皆在阴。而俞皆在阳者。何谓也。然。阴病行阳。阳病行阴。故令募在阴。俞在阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100067}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。五脏募皆在阴。而俞皆在阳者。何谓也。然。阴病行阳。阳病行阴。故令募在阴。俞在阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K8F5I2foylI', 1, '{"title":"六十八难","description":"<p>1、曰。五脏六腑。皆有井。荥。俞。经。合。皆何所主。然。经言所出为井。所流为荥。所注为俞。所行为经。所入为合。井主心下满。荥主身热。俞主体重节痛。经主喘咳寒热。合主逆气而泄。此五脏六腑井。荥。俞。经。合所主病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100068}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。五脏六腑。皆有井。荥。俞。经。合。皆何所主。然。经言所出为井。所流为荥。所注为俞。所行为经。所入为合。井主心下满。荥主身热。俞主体重节痛。经主喘咳寒热。合主逆气而泄。此五脏六腑井。荥。俞。经。合所主病也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T8xYJuNjH98', 1, '{"title":"六十九难","description":"<p>1、曰。经言。虚者补之。实者泻之。不实不虚。以经取之。何谓也。然。虚者补其母。实者泻其子。当先补之。然后泻之。不实不虚。以经取之者。是正经自生病。不中他邪也。当自取其经。故言以经取之。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100069}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。虚者补之。实者泻之。不实不虚。以经取之。何谓也。然。虚者补其母。实者泻其子。当先补之。然后泻之。不实不虚。以经取之者。是正经自生病。不中他邪也。当自取其经。故言以经取之。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4a5zRsikNNk', 1, '{"title":"七十难","description":"<p>1、曰。春夏刺浅。秋冬刺深者。何谓也。然。春夏者。阳气在上。人气亦在上。故当浅取之。秋冬者。阳气在下。人气亦在下。故当深取之。</p><p>2、春夏各致一阴。秋冬各致一阳者。何谓也。然。春夏温。必致一阴者。初下针。沉之至肾肝之部。得气。引持之阴也。秋冬寒。必致一阳者。初内针。浅而浮之至心肺之部。得气。推内之阳也。是谓春夏必致一阴。秋冬必致一阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100070}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。春夏刺浅。秋冬刺深者。何谓也。然。春夏者。阳气在上。人气亦在上。故当浅取之。秋冬者。阳气在下。人气亦在下。故当深取之。 2、春夏各致一阴。秋冬各致一阳者。何谓也。然。春夏温。必致一阴者。初下针。沉之至肾肝之部。得气。引持之阴也。秋冬寒。必致一阳者。初内针。浅而浮之至心肺之部。得气。推内之阳也。是谓春夏必致一阴。秋冬必致一阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fj4DqZBGG6f', 1, '{"title":"七十一难","description":"<p>1、曰。经言。刺荣无伤卫。刺卫无伤荣。何谓也。然。针阳者。卧针而刺之。刺阴者。先以左手摄按所针荥俞之处。气散乃内针。是谓刺荣无伤卫。刺卫无伤荣也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100071}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。刺荣无伤卫。刺卫无伤荣。何谓也。然。针阳者。卧针而刺之。刺阴者。先以左手摄按所针荥俞之处。气散乃内针。是谓刺荣无伤卫。刺卫无伤荣也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3fbhFdNShAN', 1, '{"title":"七十二难","description":"<p>1、曰。经言。能知迎随之气。可令调之。调气之方。必在阴阳。何谓也。然。所谓迎随者。知荣卫之流行。经脉之往来也。随其逆顺而取之。故曰迎随。调气之方。必在阴阳者。知其内外表里。随其阴阳而调之。故曰调气之方。必在阴阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100072}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。能知迎随之气。可令调之。调气之方。必在阴阳。何谓也。然。所谓迎随者。知荣卫之流行。经脉之往来也。随其逆顺而取之。故曰迎随。调气之方。必在阴阳者。知其内外表里。随其阴阳而调之。故曰调气之方。必在阴阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7RZ9W2zubNS', 1, '{"title":"七十三难","description":"<p>1、曰。诸井者。肌肉浅薄。气少不足使也。刺之奈何。然。诸井者。木也。荥者。火也。火者。木之子。当刺井者。以荥泻之。故经言。补者不可以为泻。泻者不可以为补。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100073}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。诸井者。肌肉浅薄。气少不足使也。刺之奈何。然。诸井者。木也。荥者。火也。火者。木之子。当刺井者。以荥泻之。故经言。补者不可以为泻。泻者不可以为补。此之谓也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kqd3xvEDFRs', 1, '{"title":"七十四难","description":"<p>1、曰。经言。春刺井。夏刺荥。季夏刺俞。秋刺经。冬刺合者。何谓也。然。春刺井者。邪在肝。夏刺荥者。邪在心。季夏刺俞者。邪在脾。秋刺经者。邪在肺。冬刺合者。邪在肾。</p><p>2、其肝。心。脾。肺。肾。而系于春。夏。秋。冬者。何也。然。五脏一病。辄有五也$l{一本言五色}。假令肝病。色青者肝也。臊臭者肝也。喜酸者肝也。喜呼者肝也。喜泣者。肝也。其病众多。不可尽言也。四时有数。而并系于春。夏。秋。冬者也。针之要妙。在于秋毫者也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100074}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。春刺井。夏刺荥。季夏刺俞。秋刺经。冬刺合者。何谓也。然。春刺井者。邪在肝。夏刺荥者。邪在心。季夏刺俞者。邪在脾。秋刺经者。邪在肺。冬刺合者。邪在肾。 2、其肝。心。脾。肺。肾。而系于春。夏。秋。冬者。何也。然。五脏一病。辄有五也$l{一本言五色}。假令肝病。色青者肝也。臊臭者肝也。喜酸者肝也。喜呼者肝也。喜泣者。肝也。其病众多。不可尽言也。四时有数。而并系于春。夏。秋。冬者也。针之要妙。在于秋毫者也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fsu8Q1qeZ7y', 1, '{"title":"七十五难","description":"<p>1、曰。经言。东方实。西方虚。泻南方。补北方。何谓也。然。金。木。水。火。土。当更相平。东方木也。西方金也。木欲实。金当平之。火欲实。水当平之。土欲实。木当平之。金欲实。火当平之。水欲实。土当平之。东方肝也。则知肝实。西方肺也。则知肺虚。泻南方火。补北方水。南方火。火者。木之子也。北方水。水者。木之母也。水胜火。子能令母实。母能令子虚。故泻火补水。欲令金不得平木也。经曰。不能治其虚。何问其余。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100075}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。东方实。西方虚。泻南方。补北方。何谓也。然。金。木。水。火。土。当更相平。东方木也。西方金也。木欲实。金当平之。火欲实。水当平之。土欲实。木当平之。金欲实。火当平之。水欲实。土当平之。东方肝也。则知肝实。西方肺也。则知肺虚。泻南方火。补北方水。南方火。火者。木之子也。北方水。水者。木之母也。水胜火。子能令母实。母能令子虚。故泻火补水。欲令金不得平木也。经曰。不能治其虚。何问其余。此之谓也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tl8kmKMLqCn', 1, '{"title":"七十六难","description":"<p>1、曰。何谓补泻。当补之时。何所取气。当泻之时。何所置气。然。当补之时。从卫取气。当泻之时。从荣置气。其阳气不足。阴气有余。当先补其阳。而后泻其阴。阴气不足。阳气有余。当先补其阴。而后泻其阳。营卫通行。此其要也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100076}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。何谓补泻。当补之时。何所取气。当泻之时。何所置气。然。当补之时。从卫取气。当泻之时。从荣置气。其阳气不足。阴气有余。当先补其阳。而后泻其阴。阴气不足。阳气有余。当先补其阴。而后泻其阳。营卫通行。此其要也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('muLwc6HMnjw', 1, '{"title":"七十七难","description":"<p>1、曰。经言。上工治未病。中工治已病。何谓也。然。所谓治未病者。见肝之病。则知肝当传之与脾。故先实其脾气。无令得受肝之邪。故曰治未病焉。中工者。见肝之病。不晓相传。但一心治肝。故曰治已病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100077}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。上工治未病。中工治已病。何谓也。然。所谓治未病者。见肝之病。则知肝当传之与脾。故先实其脾气。无令得受肝之邪。故曰治未病焉。中工者。见肝之病。不晓相传。但一心治肝。故曰治已病也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oudBDravpli', 1, '{"title":"七十八难","description":"<p>1、曰。针有补泻。何谓也。然。补泻之法。非必呼吸出内针也。知为针者。信其左。不知为针者。信其右。当刺之时。先以左手厌按所针荥。俞之处。弹面努之。爪而下之。其气之来。如动脉之状。顺针而刺之。得气。因推而内之。是谓补。动而伸之。是谓泻。不得气。乃与。男外女内。不得气。是为十死不治也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100078}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。针有补泻。何谓也。然。补泻之法。非必呼吸出内针也。知为针者。信其左。不知为针者。信其右。当刺之时。先以左手厌按所针荥。俞之处。弹面努之。爪而下之。其气之来。如动脉之状。顺针而刺之。得气。因推而内之。是谓补。动而伸之。是谓泻。不得气。乃与。男外女内。不得气。是为十死不治也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E9pAdZHgDSF', 1, '{"title":"七十九难","description":"<p>1、曰。经言。迎而夺之。安得无虚。随而济之。安得无实。虚之与实。若得若失。实之与虚。若有若无。何谓也。然。迎而夺之者。泻其子也。随而济之者。补其母也。假令心病。泻手心主俞。是谓迎而夺之者也。补手心主井。是谓随而济之者也。所谓实之与虚者。牢濡之意也。气来实牢者为得。濡虚者为失。故曰若得若失也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100079}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。迎而夺之。安得无虚。随而济之。安得无实。虚之与实。若得若失。实之与虚。若有若无。何谓也。然。迎而夺之者。泻其子也。随而济之者。补其母也。假令心病。泻手心主俞。是谓迎而夺之者也。补手心主井。是谓随而济之者也。所谓实之与虚者。牢濡之意也。气来实牢者为得。濡虚者为失。故曰若得若失也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SUK2kdP90Ib', 1, '{"title":"八十难","description":"<p>1、曰。经言。有见如入。有见如出者。何谓也。然。所谓有见如入。有见如出者。谓左手见气来至。乃内针。针入。见气尽。乃出针。是谓有见如入。有见如出也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100080}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。有见如入。有见如出者。何谓也。然。所谓有见如入。有见如出者。谓左手见气来至。乃内针。针入。见气尽。乃出针。是谓有见如入。有见如出也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mngZ60DWwSQ', 1, '{"title":"八十一难","description":"<p>1、曰。经言。无实实虚虚。损不足而益有余。是寸口脉耶。将病自有虚实耶。其损益奈何。然。是病。非谓寸口脉也。谓病自有虚实也。假令肝实而肺虚。肝者木也。肺者金也。金木当更相平。当知金平木。假令肺实而肝虚。微少气。用针不补其肝。而反重实其肺。故曰实实虚虚。损不足而益有余。此者。中工之所害也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","section":20100081}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。无实实虚虚。损不足而益有余。是寸口脉耶。将病自有虚实耶。其损益奈何。然。是病。非谓寸口脉也。谓病自有虚实也。假令肝实而肺虚。肝者木也。肺者金也。金木当更相平。当知金平木。假令肺实而肝虚。微少气。用针不补其肝。而反重实其肺。故曰实实虚虚。损不足而益有余。此者。中工之所害也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2etYuqYGaaF', 4, '{"title":"第20100001条・一难","description":"<p>1、曰。十二经皆有动脉。独取寸口。以决五脏六腑死生吉凶之法。何谓也。然。寸口者。脉之大会。手太阴之脉动也。人一呼脉行三寸。一吸脉行三寸。呼吸定息。脉行六寸。人一日一夜。凡一万三千五百息。脉行五十度。周于身。漏水下百刻。营卫行阳二十五度。行阴亦二十五度。为一周也。故五十度复会于手太阴。寸口者。五脏六腑之所终始。故法取于寸口也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。十二经皆有动脉。独取寸口。以决五脏六腑死生吉凶之法。何谓也。然。寸口者。脉之大会。手太阴之脉动也。人一呼脉行三寸。一吸脉行三寸。呼吸定息。脉行六寸。人一日一夜。凡一万三千五百息。脉行五十度。周于身。漏水下百刻。营卫行阳二十五度。行阴亦二十五度。为一周也。故五十度复会于手太阴。寸口者。五脏六腑之所终始。故法取于寸口也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4v7Y70NSZVO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wxhR9156FpF', 4, '{"title":"第20100002条・二难","description":"<p>1、曰。脉有尺寸。何谓也。然。尺寸者。脉之大要会也。从关至尺是尺内。阴之所治也。从关至鱼际是寸内。阳之所治也。故分寸为尺。分尺为寸。故阴得尺内一寸。阳得寸内九分。尺寸终始。一寸九分。故曰尺寸也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有尺寸。何谓也。然。尺寸者。脉之大要会也。从关至尺是尺内。阴之所治也。从关至鱼际是寸内。阳之所治也。故分寸为尺。分尺为寸。故阴得尺内一寸。阳得寸内九分。尺寸终始。一寸九分。故曰尺寸也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5SN2vhHWk3J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mo3RbjhXuL8', 4, '{"title":"第20100003条・三难","description":"<p>1、曰。脉有太过。有不及。有阴阳相乘。有覆有溢。有关有格。何谓也。然。关之前者。阳之动也。脉当见九分而浮。过者。法曰太过。减者。法曰不及。遂上鱼为溢。为外关内格。此阴乘之脉也。关之后者。阴之动也。脉当见一寸而沉。过者。法曰太过。减者。法曰不及。遂入尺为覆。为内关外格。此阳乘之脉也。故曰覆溢。是其真脏之脉。人不病而死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有太过。有不及。有阴阳相乘。有覆有溢。有关有格。何谓也。然。关之前者。阳之动也。脉当见九分而浮。过者。法曰太过。减者。法曰不及。遂上鱼为溢。为外关内格。此阴乘之脉也。关之后者。阴之动也。脉当见一寸而沉。过者。法曰太过。减者。法曰不及。遂入尺为覆。为内关外格。此阳乘之脉也。故曰覆溢。是其真脏之脉。人不病而死也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Niqp0TpCfqf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0TEzHZxl2L', 4, '{"title":"第20100004条・四难","description":"<p>1、曰。脉有阴阳之法。何谓也。然。呼出心与肺。吸入肾与肝。呼吸之间。脾也其脉在中。浮者阳也。沉者阴也。故曰阴阳也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有阴阳之法。何谓也。然。呼出心与肺。吸入肾与肝。呼吸之间。脾也其脉在中。浮者阳也。沉者阴也。故曰阴阳也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '71L3XW5G7n9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G6jFnlUypU4', 4, '{"title":"第20100005条・四难","description":"<p>2、心肺俱浮。何以别之。然。浮而大散者心也浮而短涩者肺也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2、心肺俱浮。何以别之。然。浮而大散者心也浮而短涩者肺也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '71L3XW5G7n9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H4dfWLuvjI7', 4, '{"title":"第20100006条・四难","description":"<p>3、肾肝俱沉。何以别之。然。牢而长者肝也。按之濡。举指来实者肾也。脾者中州。故其脉在中。是阴阳之法也。脉有一阴一阳。一阴二阳。一阴三阳。有一阳一阴。一阳二阴。一阳三阴。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '3、肾肝俱沉。何以别之。然。牢而长者肝也。按之濡。举指来实者肾也。脾者中州。故其脉在中。是阴阳之法也。脉有一阴一阳。一阴二阳。一阴三阳。有一阳一阴。一阳二阴。一阳三阴。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '71L3XW5G7n9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CQVZzFBI7g9', 4, '{"title":"第20100007条・四难","description":"<p>4、如此之言。寸口有六脉俱动邪。然。此言者。非有六脉俱动也。谓浮。沉。长。短。滑。涩也。浮者阳也。滑者阳也。长者阳也。沉者阴也。短者阴也。涩者阴也。所谓一阴一阳者。谓脉来沉而滑也。一阴二阳者。谓脉来沉滑而长也。一阴三阳者。谓脉来浮滑而长。时一沉也。所谓一阳一阴者。谓脉来浮而涩也。一阳二阴者。谓脉来长而沉涩也。一阳三阴者。谓脉来沉涩而短。时一浮也。各以其经所在。名病顺逆也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '4、如此之言。寸口有六脉俱动邪。然。此言者。非有六脉俱动也。谓浮。沉。长。短。滑。涩也。浮者阳也。滑者阳也。长者阳也。沉者阴也。短者阴也。涩者阴也。所谓一阴一阳者。谓脉来沉而滑也。一阴二阳者。谓脉来沉滑而长也。一阴三阳者。谓脉来浮滑而长。时一沉也。所谓一阳一阴者。谓脉来浮而涩也。一阳二阴者。谓脉来长而沉涩也。一阳三阴者。谓脉来沉涩而短。时一浮也。各以其经所在。名病顺逆也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '71L3XW5G7n9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Kf9X5ttcqnq', 4, '{"title":"第20100008条・五难","description":"<p>1、曰。脉有轻重。何谓也。然。初持脉。如三菽之重。与皮毛相得者。肺部也。如六菽之重。与血脉相得者。心部也。如九菽之重。与肌肉相得者。脾部也。如十二菽之重。与筋平者。肝部也。按之至骨。举指来疾者。肾部也。故曰轻重也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有轻重。何谓也。然。初持脉。如三菽之重。与皮毛相得者。肺部也。如六菽之重。与血脉相得者。心部也。如九菽之重。与肌肉相得者。脾部也。如十二菽之重。与筋平者。肝部也。按之至骨。举指来疾者。肾部也。故曰轻重也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4ZToD5Jt164');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0PJw8lJdKND', 4, '{"title":"第20100009条・六难","description":"<p>1、曰。脉有阴盛阳虚。阳盛阴虚。何谓也。然。浮之损小。沉之实大。故曰阴盛阳虚。沉之损小。浮之实大。故曰阳盛阴虚。是阴阳虚实之意也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。脉有阴盛阳虚。阳盛阴虚。何谓也。然。浮之损小。沉之实大。故曰阴盛阳虚。沉之损小。浮之实大。故曰阳盛阴虚。是阴阳虚实之意也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'b3DxdOH3DyY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9z7aniEmZiV', 4, '{"title":"第20100010条・七难","description":"<p>1、曰。经言少阳之至。乍大乍小。乍短乍长。阳明之至。浮大而短。太阳之至。洪大而长。少阴之至。紧大而长。太阴之至。紧细而长。厥阴之至。沉短而紧。此六者。是平脉那。将病脉耶。然。皆王脉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。经言少阳之至。乍大乍小。乍短乍长。阳明之至。浮大而短。太阳之至。洪大而长。少阴之至。紧大而长。太阴之至。紧细而长。厥阴之至。沉短而紧。此六者。是平脉那。将病脉耶。然。皆王脉也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'W7bM78OhZew');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5AGJTfW57ft', 4, '{"title":"第20100011条・七难","description":"<p>2、其气以何月。各王几日。然。冬至之后。初得甲子少阳王。复得甲子阳明王。复得甲子太阳王。复得甲子少阴王。复得甲子太阴王。复得甲子厥阴王。王各六十日。六六三百六十日。以成一岁。此三阳三阴之王时日大要也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2、其气以何月。各王几日。然。冬至之后。初得甲子少阳王。复得甲子阳明王。复得甲子太阳王。复得甲子少阴王。复得甲子太阴王。复得甲子厥阴王。王各六十日。六六三百六十日。以成一岁。此三阳三阴之王时日大要也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'W7bM78OhZew');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZuhhNY2B81r', 4, '{"title":"第20100012条・八难","description":"<p>1、曰。寸口脉平而死者。何谓也。然。诸十二经脉者。皆系于生气之原。所谓生气之原者。谓十二经之根本也。谓肾间动气也。此五脏六腑之本。十二经脉之根。呼吸之门。三焦之原。一名守邪之神。故气者。人之根本也。根绝则茎叶枯矣。寸口脉平而死者。生气独绝于内也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '2024-09-26T13:56:07.000Z', '1、曰。寸口脉平而死者。何谓也。然。诸十二经脉者。皆系于生气之原。所谓生气之原者。谓十二经之根本也。谓肾间动气也。此五脏六腑之本。十二经脉之根。呼吸之门。三焦之原。一名守邪之神。故气者。人之根本也。根绝则茎叶枯矣。寸口脉平而死者。生气独绝于内也。', '2024-09-26T13:56:07.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'd2TVrQIHYWO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5YgiSNtqvOc', 4, '{"title":"第20100013条・九难","description":"<p>1、曰。何以别知脏腑之病耶。然。数者腑也。迟者脏也。数则为热。迟则为寒。诸阳为热。诸阴为寒。故以别知脏腑之病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。何以别知脏腑之病耶。然。数者腑也。迟者脏也。数则为热。迟则为寒。诸阳为热。诸阴为寒。故以别知脏腑之病也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '2Qv91AdOD6H');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MHL238HTJXs', 4, '{"title":"第20100014条・十难","description":"<p>1、曰。一脉为十变者。何谓也。然。五邪刚柔相逢之意也。假令心脉急甚者。肝邪干心也。心脉微急者。胆邪干小肠也。心脉大甚者。心邪自干心也。心脉微大者。小肠邪自干小肠也。心脉缓甚者。脾邪干心也。心脉微缓者。胃邪于小肠也。心脉涩甚者。肺邪干心也。心脉微涩者。大肠邪干小肠也。心脉沉甚者。肾邪干心也。心脉微沉者。膀胱邪干小肠也。五脏各有刚柔邪。故令一脉辄变为十也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。一脉为十变者。何谓也。然。五邪刚柔相逢之意也。假令心脉急甚者。肝邪干心也。心脉微急者。胆邪干小肠也。心脉大甚者。心邪自干心也。心脉微大者。小肠邪自干小肠也。心脉缓甚者。脾邪干心也。心脉微缓者。胃邪于小肠也。心脉涩甚者。肺邪干心也。心脉微涩者。大肠邪干小肠也。心脉沉甚者。肾邪干心也。心脉微沉者。膀胱邪干小肠也。五脏各有刚柔邪。故令一脉辄变为十也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'XdQ0dfKagOt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vxN556Uc0xd', 4, '{"title":"第20100015条・十一难","description":"<p>1、曰。经言脉不满五十动而一止。一脏无气者。何脏也。然。人吸者随阴入。呼者因阳出。今吸不能至肾。至肝而还。故知一脏无气者。肾气先尽也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言脉不满五十动而一止。一脏无气者。何脏也。然。人吸者随阴入。呼者因阳出。今吸不能至肾。至肝而还。故知一脏无气者。肾气先尽也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'F56sQb5MpOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gxg0QO1BQnz', 4, '{"title":"第20100016条・十二难","description":"<p>1、曰。经言五脏脉已绝于内。用针者反实其外。五脏脉已绝于外。用针者反实其内。内外之绝。何以别之。然。五脏脉已绝于内者。肾肝气已绝于内也。而医反补其心肺。五脏脉已绝于外者。心肺气已绝于外也。而医反补其肾肝。阳绝补阴。阴绝补阳。是谓实实虚虚。损不足而益有余。如此死者。医杀之耳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言五脏脉已绝于内。用针者反实其外。五脏脉已绝于外。用针者反实其内。内外之绝。何以别之。然。五脏脉已绝于内者。肾肝气已绝于内也。而医反补其心肺。五脏脉已绝于外者。心肺气已绝于外也。而医反补其肾肝。阳绝补阴。阴绝补阳。是谓实实虚虚。损不足而益有余。如此死者。医杀之耳。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '8h9L46yCCoe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yid92WZ8LeY', 4, '{"title":"第20100017条・十三难","description":"<p>1、曰。经言见其色而不得其脉。反得相胜之脉者即死。得相生之脉者。病即自己。色之与脉当参相应。为之奈何。然。五脏有五色。皆见于面。亦当与寸口。尺内相应。假令色青。其脉当弦而急。色赤。其脉浮大而散。色黄。其脉中缓而大。色白。其脉浮涩而短。色黑。其脉沉濡而滑。此所谓五色之与脉。当参相应也。脉数。尺之皮肤亦数。脉急。尺之皮肤亦急。脉缓。尺之皮肤亦缓。脉涩。尺之皮肤亦涩。脉滑。尺之皮肤亦滑。五脏各有声。色。臭。味。当与寸口。尺内相应。其不应者病也。假令色青。其脉浮涩而短。若大而缓为相胜。浮大而散。若小而滑为相生也。经言知一为下工。知二为中工。知三为上工。上工者十全九。中工者十全七。下工者十全六。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言见其色而不得其脉。反得相胜之脉者即死。得相生之脉者。病即自己。色之与脉当参相应。为之奈何。然。五脏有五色。皆见于面。亦当与寸口。尺内相应。假令色青。其脉当弦而急。色赤。其脉浮大而散。色黄。其脉中缓而大。色白。其脉浮涩而短。色黑。其脉沉濡而滑。此所谓五色之与脉。当参相应也。脉数。尺之皮肤亦数。脉急。尺之皮肤亦急。脉缓。尺之皮肤亦缓。脉涩。尺之皮肤亦涩。脉滑。尺之皮肤亦滑。五脏各有声。色。臭。味。当与寸口。尺内相应。其不应者病也。假令色青。其脉浮涩而短。若大而缓为相胜。浮大而散。若小而滑为相生也。经言知一为下工。知二为中工。知三为上工。上工者十全九。中工者十全七。下工者十全六。此之谓也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '9fZG3HcpKZg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iDjKh8Eu9ta', 4, '{"title":"第20100018条・十四难","description":"<p>1、曰。脉有损。至。何谓也。然。至之脉。一呼再至曰平。三至曰离经。四至曰夺精。五至曰死。六至曰命绝。此至之脉也。何谓损。一呼一至曰离经。再呼一至曰夺精。三呼一至曰死。四呼一至曰命绝。此损之脉也。至脉从下上。损脉从上下也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有损。至。何谓也。然。至之脉。一呼再至曰平。三至曰离经。四至曰夺精。五至曰死。六至曰命绝。此至之脉也。何谓损。一呼一至曰离经。再呼一至曰夺精。三呼一至曰死。四呼一至曰命绝。此损之脉也。至脉从下上。损脉从上下也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qiYk7lEMJy5', 4, '{"title":"第20100019条・十四难","description":"<p>2、损脉之为病奈何。然。一损损于皮毛。皮聚而毛落。二损损于血脉。血脉虚少。不能荣于五脏六腑。三损损于肌肉。肌肉消瘦。饮食不能为肌肤。四损损于筋。筋缓不能自收持。五损损于骨。骨痿不能起于床。反此者。至脉之病也。从上下者。骨痿不能起于床者死。从下上者。皮聚而毛落者死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2、损脉之为病奈何。然。一损损于皮毛。皮聚而毛落。二损损于血脉。血脉虚少。不能荣于五脏六腑。三损损于肌肉。肌肉消瘦。饮食不能为肌肤。四损损于筋。筋缓不能自收持。五损损于骨。骨痿不能起于床。反此者。至脉之病也。从上下者。骨痿不能起于床者死。从下上者。皮聚而毛落者死。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UCh22NPSmTk', 4, '{"title":"第20100020条・十四难","description":"<p>3、治损之法奈何。然。损其肺者。益其气。损其心者。调其荣卫。损其脾者。调其饮食。适其寒温。损其肝者。缓其中。损其肾者。益其精。此治损之法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '3、治损之法奈何。然。损其肺者。益其气。损其心者。调其荣卫。损其脾者。调其饮食。适其寒温。损其肝者。缓其中。损其肾者。益其精。此治损之法也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J3OuRvyZFJG', 4, '{"title":"第20100021条・十四难","description":"<p>4、脉有一呼再至。一吸再至。有一呼三至。一吸三至。有一呼四至。一吸四至。有一呼五至。一吸五至。一呼六至。一吸六至。有一呼一至。一吸一至。有再呼一至。再吸一至。有呼吸再至。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '4、脉有一呼再至。一吸再至。有一呼三至。一吸三至。有一呼四至。一吸四至。有一呼五至。一吸五至。一呼六至。一吸六至。有一呼一至。一吸一至。有再呼一至。再吸一至。有呼吸再至。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y79tmZ0IpMQ', 4, '{"title":"第20100022条・十四难","description":"<p>5、脉来如此。何以别知其病也。然。脉来一呼再至。一吸再至。不大不小曰平。一呼三至。一吸三至。为适得其病。前大后小。即头痛。目眩。前小后大。即胸满。短气。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '5、脉来如此。何以别知其病也。然。脉来一呼再至。一吸再至。不大不小曰平。一呼三至。一吸三至。为适得其病。前大后小。即头痛。目眩。前小后大。即胸满。短气。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iuIDuwVHabE', 4, '{"title":"第20100023条・十四难","description":"<p>6、一呼四至。一吸四至。病欲甚。脉洪大者。苦烦满。沉细者。腹中痛。滑者。伤热。涩者。中雾露。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '6、一呼四至。一吸四至。病欲甚。脉洪大者。苦烦满。沉细者。腹中痛。滑者。伤热。涩者。中雾露。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0TLjZrXH2e7', 4, '{"title":"第20100024条・十四难","description":"<p>7、一呼五至。一吸五至。其人当困。沉细夜加。浮大昼加。不大不小。虽困可治。其有大小者。为难治。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '7、一呼五至。一吸五至。其人当困。沉细夜加。浮大昼加。不大不小。虽困可治。其有大小者。为难治。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OyoHZhpoEYK', 4, '{"title":"第20100025条・十四难","description":"<p>8、一呼六至。一吸六至。为死脉也。沉细夜死。浮大昼死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '8、一呼六至。一吸六至。为死脉也。沉细夜死。浮大昼死。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WkeSt5Q1R7m', 4, '{"title":"第20100026条・十四难","description":"<p>9、一呼一至。一吸一至。名曰损。人虽能行。犹当着床。所以然者。血气皆不足故也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '9、一呼一至。一吸一至。名曰损。人虽能行。犹当着床。所以然者。血气皆不足故也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('brzKZQgv8wM', 4, '{"title":"第20100027条・十四难","description":"<p>10、再呼一至。再吸一至。$l{呼吸再至}名曰无魂。无魂者当死也。人虽能行。名曰行尸。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '10、再呼一至。再吸一至。$l{呼吸再至}名曰无魂。无魂者当死也。人虽能行。名曰行尸。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qnuM4RoLkQj', 4, '{"title":"第20100028条・十四难","description":"<p>11、上部有脉。下部无脉。其人当吐。不吐者死。上部无脉。下部有脉。虽困无能为害。所以然者。人之有尺。譬如树之有根。枝叶虽枯槁。根本将自生。脉有根本。人有元气。故知不死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '11、上部有脉。下部无脉。其人当吐。不吐者死。上部无脉。下部有脉。虽困无能为害。所以然者。人之有尺。譬如树之有根。枝叶虽枯槁。根本将自生。脉有根本。人有元气。故知不死。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '0axSWCTEctJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p13zzRk3k2f', 4, '{"title":"第20100029条・十五难","description":"<p>1、曰。经言春脉弦。夏脉钩。秋脉毛。冬脉石。是王脉耶。将病脉也。然。弦。钩。毛。石者。四时之脉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言春脉弦。夏脉钩。秋脉毛。冬脉石。是王脉耶。将病脉也。然。弦。钩。毛。石者。四时之脉也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BuDC4HxaLGD', 4, '{"title":"第20100030条・十五难","description":"<p>2、春脉弦者。肝东方木也。万物始生。未有枝叶。故其脉之来。濡弱而长。故曰弦。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2、春脉弦者。肝东方木也。万物始生。未有枝叶。故其脉之来。濡弱而长。故曰弦。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VsAcg2l5FL3', 4, '{"title":"第20100031条・十五难","description":"<p>3、夏脉钩者。心南方火也。万物之所茂。垂枝布叶。皆下曲如钩。故其脉之来疾去迟。故曰钩。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '3、夏脉钩者。心南方火也。万物之所茂。垂枝布叶。皆下曲如钩。故其脉之来疾去迟。故曰钩。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lmIL50QS4D4', 4, '{"title":"第20100032条・十五难","description":"<p>4、秋脉毛者。肺西方金也。万物之所终。草木华叶。皆秋而落。其枝独在。若毫毛也。故其脉之来。轻虚以浮。故曰毛。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100032,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '4、秋脉毛者。肺西方金也。万物之所终。草木华叶。皆秋而落。其枝独在。若毫毛也。故其脉之来。轻虚以浮。故曰毛。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3XJfGYyy7Uf', 4, '{"title":"第20100033条・十五难","description":"<p>5、冬脉石者。肾北方水也。万物之所藏也。盛冬之时。水凝如石。故其脉之来。沉濡而滑。故曰石。此四时之脉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '5、冬脉石者。肾北方水也。万物之所藏也。盛冬之时。水凝如石。故其脉之来。沉濡而滑。故曰石。此四时之脉也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9P2BHk0DHP7', 4, '{"title":"第20100034条・十五难","description":"<p>6、如有变奈何。然。春脉弦。反者为病。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '6、如有变奈何。然。春脉弦。反者为病。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UmeTTIiBJct', 4, '{"title":"第20100035条・十五难","description":"<p>7、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。气来厌厌聂聂。如循榆叶曰平。益实而滑。如循长竿曰病。急而劲益强。如新张弓弦曰死。春脉微弦曰平。弦多胃气少曰病。但弦无胃气曰死。春以胃气为本。夏脉钩。反者为病。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100035,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '7、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。气来厌厌聂聂。如循榆叶曰平。益实而滑。如循长竿曰病。急而劲益强。如新张弓弦曰死。春脉微弦曰平。弦多胃气少曰病。但弦无胃气曰死。春以胃气为本。夏脉钩。反者为病。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rW2ObXdXO8e', 4, '{"title":"第20100036条・十五难","description":"<p>8、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来累累如环。如循琅玕曰平。来而益数。如鸡举足者曰病。前曲后居。如操带钩曰死。夏脉微钩曰平。钩多胃气少曰病。但钩无胃气曰死。夏以胃气为本。秋脉毛。反者为病。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '8、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来累累如环。如循琅玕曰平。来而益数。如鸡举足者曰病。前曲后居。如操带钩曰死。夏脉微钩曰平。钩多胃气少曰病。但钩无胃气曰死。夏以胃气为本。秋脉毛。反者为病。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pgvjZHIf7xl', 4, '{"title":"第20100037条・十五难","description":"<p>9、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来蔼蔼如车盖。按之益大曰平。不上不下。如循鸡羽曰病。按之萧索。如风吹毛曰死。秋脉微毛曰平。毛多胃气少曰病。但毛无胃气。曰死。秋以胃气为本。冬脉石。反者为病。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '9、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。其脉来蔼蔼如车盖。按之益大曰平。不上不下。如循鸡羽曰病。按之萧索。如风吹毛曰死。秋脉微毛曰平。毛多胃气少曰病。但毛无胃气。曰死。秋以胃气为本。冬脉石。反者为病。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('29jetsPhXak', 4, '{"title":"第20100038条・十五难","description":"<p>10、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。脉来上大下兑。濡滑如雀之喙。曰平。啄啄连属。其中微曲。曰病。来如解索。去如弹石。曰死。冬脉微石。曰平。石多胃气少。曰病。但石无胃气。曰死。冬以胃气为本。胃者。水谷之海。主禀。四时皆以胃气为本。是谓四时之变病。死生之要会也。脾者。中州也。其平和不可得见。衰乃见耳。来如雀之啄。如水之下漏。是脾衰之见也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '10、何谓反。然。其气来实强。是谓太过。病在外。气来虚微。是谓不及。病在内。脉来上大下兑。濡滑如雀之喙。曰平。啄啄连属。其中微曲。曰病。来如解索。去如弹石。曰死。冬脉微石。曰平。石多胃气少。曰病。但石无胃气。曰死。冬以胃气为本。胃者。水谷之海。主禀。四时皆以胃气为本。是谓四时之变病。死生之要会也。脾者。中州也。其平和不可得见。衰乃见耳。来如雀之啄。如水之下漏。是脾衰之见也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaf2wXvxleI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rOS0Skj4QH1', 4, '{"title":"第20100039条・十六难","description":"<p>1、曰。脉有三部九候。有阴阳。有轻重。有六十首。一脉变为四时。离圣久远。各自是其法。何以别之。然。是其病。有内外证。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100039,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有三部九候。有阴阳。有轻重。有六十首。一脉变为四时。离圣久远。各自是其法。何以别之。然。是其病。有内外证。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7AOsvNtglyc', 4, '{"title":"第20100040条・十六难","description":"<p>2、其病为之奈何。然。假令得肝脉。其外证。善洁。面青。善怒。其内证。脐左有动气。按之牢若痛。其病。四肢满。闭淋$l{一作癃}。溲便难。转筋。有是者肝也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100040,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2、其病为之奈何。然。假令得肝脉。其外证。善洁。面青。善怒。其内证。脐左有动气。按之牢若痛。其病。四肢满。闭淋$l{一作癃}。溲便难。转筋。有是者肝也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZNtKM2hAu43', 4, '{"title":"第20100041条・十六难","description":"<p>3、假令得心脉。其外证。面赤。口干。喜笑。其内证。脐上有动气。按之牢若痛。其病。烦心。心痛。掌中热而啘。有是者心也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100041,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '3、假令得心脉。其外证。面赤。口干。喜笑。其内证。脐上有动气。按之牢若痛。其病。烦心。心痛。掌中热而啘。有是者心也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ySfiKzyrfTi', 4, '{"title":"第20100042条・十六难","description":"<p>4、假令得脾脉。其外证。面黄。善噫。善思。善味。其内证。当脐有动气。按之牢若痛。其病。腹胀满。食不消。体重节痛。怠惰嗜卧。四肢不收。有是者脾也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100042,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '4、假令得脾脉。其外证。面黄。善噫。善思。善味。其内证。当脐有动气。按之牢若痛。其病。腹胀满。食不消。体重节痛。怠惰嗜卧。四肢不收。有是者脾也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AnKHdiBqei8', 4, '{"title":"第20100043条・十六难","description":"<p>5、假令得肺脉。其外证。面白。善嚏。悲愁不乐。欲哭。其内证。脐右有动气。按之牢若痛。其病。喘咳。洒淅寒热。有是者肺也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100043,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '5、假令得肺脉。其外证。面白。善嚏。悲愁不乐。欲哭。其内证。脐右有动气。按之牢若痛。其病。喘咳。洒淅寒热。有是者肺也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('caW47RKxNsy', 4, '{"title":"第20100044条・十六难","description":"<p>6、假令得肾脉。其外证。面黑。善恐欠。其内证。脐下有动气。按之牢若痛。其病。逆气。小腹急痛。泄如下重。足胫寒而逆。有是者肾也。无是者非也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100044,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '6、假令得肾脉。其外证。面黑。善恐欠。其内证。脐下有动气。按之牢若痛。其病。逆气。小腹急痛。泄如下重。足胫寒而逆。有是者肾也。无是者非也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5yyBy10WdTF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t619TJkvhNr', 4, '{"title":"第20100045条・十七难","description":"<p>1、曰。经言病或有死。或有不治自愈。或连年月不已。其死生存亡。可切脉而知之耶。然。可尽知也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100045,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。经言病或有死。或有不治自愈。或连年月不已。其死生存亡。可切脉而知之耶。然。可尽知也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VCf05Rp2lz8', 4, '{"title":"第20100046条・十七难","description":"<p>2、诊病若闭目不欲见人者。脉当得肝脉强急而长。反得肺脉浮短而涩者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100046,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2、诊病若闭目不欲见人者。脉当得肝脉强急而长。反得肺脉浮短而涩者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7alwYsEthJC', 4, '{"title":"第20100047条・十七难","description":"<p>3、病若开目而渴。心下牢者。脉当得紧实而数。而反得沉涩而微者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100047,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '3、病若开目而渴。心下牢者。脉当得紧实而数。而反得沉涩而微者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IA66SleNnIt', 4, '{"title":"第20100048条・十七难","description":"<p>4、病若吐血。复鼽衄血者。脉当沉细。而反浮大而牢者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100048,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '4、病若吐血。复鼽衄血者。脉当沉细。而反浮大而牢者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nHL18J1eQ3j', 4, '{"title":"第20100049条・十七难","description":"<p>5、病若谵言妄语。身当有热。脉当洪大。而反手足厥逆。脉沉细而微者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100049,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '5、病若谵言妄语。身当有热。脉当洪大。而反手足厥逆。脉沉细而微者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qGqZ5csro7h', 4, '{"title":"第20100050条・十七难","description":"<p>6、病若大腹而泄者。脉当微细而涩。反紧大而滑者。死也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100050,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '6、病若大腹而泄者。脉当微细而涩。反紧大而滑者。死也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'I2r9Elg0dXT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yG4b0vfNhZ5', 4, '{"title":"第20100051条・十八难","description":"<p>1、曰。脉有三部。部有四经。手有太阴。阳明。足有太阳。少阴。为上下部。何谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100051,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '1、曰。脉有三部。部有四经。手有太阴。阳明。足有太阳。少阴。为上下部。何谓也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lkVY9WMm6MZ', 4, '{"title":"第20100052条・十八难","description":"<p>2、然。手太阴。阳明金也。足少阴。太阳水也。金生水。水流下行而不能上。故在下部也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100052,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2、然。手太阴。阳明金也。足少阴。太阳水也。金生水。水流下行而不能上。故在下部也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PxYBJxRzrUQ', 4, '{"title":"第20100053条・十八难","description":"<p>3、足厥阴。少阳木也。生手太阳。少阴火。火炎上行而不能下。故为上部。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100053,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '3、足厥阴。少阳木也。生手太阳。少阴火。火炎上行而不能下。故为上部。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('01agSOqO3Kj', 4, '{"title":"第20100054条・十八难","description":"<p>4、手心主。少阳火。生足太阴。阳明土。土主中宫。故在中部也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100054,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '4、手心主。少阳火。生足太阴。阳明土。土主中宫。故在中部也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s8SbzHr0Jo0', 4, '{"title":"第20100055条・十八难","description":"<p>5、此皆五行子母更相生养者也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100055,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '5、此皆五行子母更相生养者也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fF6TFCtfn6I', 4, '{"title":"第20100056条・十八难","description":"<p>6、脉有三部九侯。各何主之。然。三部者。寸。关。尺也。九侯者。浮。中。沉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100056,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '6、脉有三部九侯。各何主之。然。三部者。寸。关。尺也。九侯者。浮。中。沉也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KGqZlfBu6BK', 4, '{"title":"第20100057条・十八难","description":"<p>7、上部法天。主胸上至头之有疾也。中部法人。主鬲以下至脐之有疾也。下部法地。主脐以下至足之有疾也。审而刺之者也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100057,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '7、上部法天。主胸上至头之有疾也。中部法人。主鬲以下至脐之有疾也。下部法地。主脐以下至足之有疾也。审而刺之者也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UyjZTSGiNc4', 4, '{"title":"第20100058条・十八难","description":"<p>8、人病有沉滞久积聚。可切脉而知之耶。然。诊病在右胁有积气。得肺脉。结脉。结甚则积甚。结微则气微。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100058,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '8、人病有沉滞久积聚。可切脉而知之耶。然。诊病在右胁有积气。得肺脉。结脉。结甚则积甚。结微则气微。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hOaaxpottqc', 4, '{"title":"第20100059条・十八难","description":"<p>9、诊不得肺脉。而右胁有积气者。何也。然。肺脉虽不见。右手脉当沉伏。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100059,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '9、诊不得肺脉。而右胁有积气者。何也。然。肺脉虽不见。右手脉当沉伏。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nxUL8FS7A9N', 4, '{"title":"第20100060条・十八难","description":"<p>10、其外痼疾同法耶。将异也。然。结者。脉来去时一止。无常数。名曰结也。伏者。脉行筋下也。浮者。脉在肉上行也。左右表里。法皆如此。假令脉结伏者。内无积聚。脉浮结者。外无痼疾。有积聚脉不结伏。有痼疾脉不浮结。为脉不应病。病不应脉。是为死病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100060,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '2024-09-26T13:56:08.000Z', '10、其外痼疾同法耶。将异也。然。结者。脉来去时一止。无常数。名曰结也。伏者。脉行筋下也。浮者。脉在肉上行也。左右表里。法皆如此。假令脉结伏者。内无积聚。脉浮结者。外无痼疾。有积聚脉不结伏。有痼疾脉不浮结。为脉不应病。病不应脉。是为死病也。', '2024-09-26T13:56:08.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'V2iJpMQx1iW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ck81a6KLotS', 4, '{"title":"第20100061条・十九难","description":"<p>1、曰。经言脉有逆顺。男女有恒$l{一本作常}。而反者。何谓也。然。男子生于寅。寅为木。阳也。女子生于申。申为金。阴也。故男脉在关上。女脉在关下。是以男子尺脉恒弱。女子尺脉恒盛。是其常也。反者。男得女脉。女得男脉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100061,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言脉有逆顺。男女有恒$l{一本作常}。而反者。何谓也。然。男子生于寅。寅为木。阳也。女子生于申。申为金。阴也。故男脉在关上。女脉在关下。是以男子尺脉恒弱。女子尺脉恒盛。是其常也。反者。男得女脉。女得男脉也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'x6sVaQMToeB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B9gxeZGcd3R', 4, '{"title":"第20100062条・十九难","description":"<p>2、其为病何如。然。男得女脉为不足。病在内。左得之。病在左。右得之。病在右。随脉言之也。女得男脉为太过。病在四肢。左得之。病在左。右得之。病在右。随脉言之。此之渭也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100062,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、其为病何如。然。男得女脉为不足。病在内。左得之。病在左。右得之。病在右。随脉言之也。女得男脉为太过。病在四肢。左得之。病在左。右得之。病在右。随脉言之。此之渭也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'x6sVaQMToeB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RNN4IVRAc4q', 4, '{"title":"第20100063条・二十难","description":"<p>1、曰。经言脉有伏匿。伏匿于何脏而言伏匿耶。然。谓阴阳更相乘更相伏也。脉居阴部而反阳脉见者。为阳乘阴也。虽阳脉时沉涩而短。此谓阳中伏阴也。脉居阳部而反阴脉见者。为阴乘阳也。虽阳脉时浮滑而长。此谓阴中伏阳也。重阳者狂。重阴者癫。脱阳者。见鬼。脱阴者。目盲。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言脉有伏匿。伏匿于何脏而言伏匿耶。然。谓阴阳更相乘更相伏也。脉居阴部而反阳脉见者。为阳乘阴也。虽阳脉时沉涩而短。此谓阳中伏阴也。脉居阳部而反阴脉见者。为阴乘阳也。虽阳脉时浮滑而长。此谓阴中伏阳也。重阳者狂。重阴者癫。脱阳者。见鬼。脱阴者。目盲。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'nsfSw4vZF81');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YLCakFFzf2R', 4, '{"title":"第20100064条・二十一难","description":"<p>1、曰。经言人形病。脉不病。曰生。脉病。形不病。曰死。何谓也。然。人形病。脉不病。非有不病者也。谓息数不应脉数也。此大法。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100064,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言人形病。脉不病。曰生。脉病。形不病。曰死。何谓也。然。人形病。脉不病。非有不病者也。谓息数不应脉数也。此大法。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'quW0IlRMAIV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nAKZwpfMnqA', 4, '{"title":"第20100065条・二十二难","description":"<p>1、曰。经言脉有是动。有所生病。一脉辄$l{一本无辄字}变为二病者。何也。然。经言是动者。气也。所生病者。血也。邪在气。气为是动。邪在血。血为所生病。气主呴之。血主濡之。气留而不行者。为气先病也。血壅而不濡者。为血后病也。故先为是动。后所生$l{一本有病字}也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100065,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经言脉有是动。有所生病。一脉辄$l{一本无辄字}变为二病者。何也。然。经言是动者。气也。所生病者。血也。邪在气。气为是动。邪在血。血为所生病。气主呴之。血主濡之。气留而不行者。为气先病也。血壅而不濡者。为血后病也。故先为是动。后所生$l{一本有病字}也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'XIB4JKp03LC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3edLaVyWuM4', 4, '{"title":"第20100066条・二十三难","description":"<p>1、曰。手足三阴三阳。脉之度数。可晓以不。然。手三阳之脉。从手至头。长五尺。五六合三丈。手三阴之脉。从手至胸中。长三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足三阳之脉。从足至头。长八尺。六八四丈八尺。足三阴之脉。从足至胸。长六尺五寸。六六三丈六尺。五六三尺。合三丈九尺。人两足跷脉。从足至目。长七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各长四尺五寸。二四八尺。二五一尺。合九尺。凡脉长一十六丈二尺。此所谓经脉长短之数也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100066,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。手足三阴三阳。脉之度数。可晓以不。然。手三阳之脉。从手至头。长五尺。五六合三丈。手三阴之脉。从手至胸中。长三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足三阳之脉。从足至头。长八尺。六八四丈八尺。足三阴之脉。从足至胸。长六尺五寸。六六三丈六尺。五六三尺。合三丈九尺。人两足跷脉。从足至目。长七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各长四尺五寸。二四八尺。二五一尺。合九尺。凡脉长一十六丈二尺。此所谓经脉长短之数也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'VMPVY1EzaYV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CXZWLujexTg', 4, '{"title":"第20100067条・二十三难","description":"<p>2、经脉十二。络脉十五。何始何穷也。然。经脉者。行血气。通阴阳。以荣于身者也。其始从中焦。注手太阴。阳明。阳明注足阳明。太阴。太阴注手少阴。太阳。太阳注足太阳。少阴。少阴注手心主。少阳。少阳注足少阳。厥阴。厥阴复还注手太阴。别络十五。皆因其原。如环无端。转相灌溉。朝于寸口。人迎。以处百病。而决死生也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100067,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、经脉十二。络脉十五。何始何穷也。然。经脉者。行血气。通阴阳。以荣于身者也。其始从中焦。注手太阴。阳明。阳明注足阳明。太阴。太阴注手少阴。太阳。太阳注足太阳。少阴。少阴注手心主。少阳。少阳注足少阳。厥阴。厥阴复还注手太阴。别络十五。皆因其原。如环无端。转相灌溉。朝于寸口。人迎。以处百病。而决死生也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'VMPVY1EzaYV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t59a6n3gyp6', 4, '{"title":"第20100068条・二十三难","description":"<p>3、经云。明知始终。阴阳定矣。何谓也。然。终始者。脉之纪也。寸口。人迎。阴阳之气通于朝使。如环无端。故曰始也。终者。三阴三阳之脉绝。绝则死。死各有形。故曰终也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100068,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '3、经云。明知始终。阴阳定矣。何谓也。然。终始者。脉之纪也。寸口。人迎。阴阳之气通于朝使。如环无端。故曰始也。终者。三阴三阳之脉绝。绝则死。死各有形。故曰终也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'VMPVY1EzaYV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GOFiDEpocBq', 4, '{"title":"第20100069条・二十四难","description":"<p>1、曰。手足三阴三阳气已绝。何以为候。可知其吉凶不。然。足少阴气绝。则骨枯。少阴者。冬脉也。伏行而濡于骨髓。故骨髓不濡。即肉不着骨。骨肉不相亲。即肉濡而却。肉濡而却。故齿长而枯。发无润泽。无润泽者。骨先死。戊日笃。己日死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100069,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。手足三阴三阳气已绝。何以为候。可知其吉凶不。然。足少阴气绝。则骨枯。少阴者。冬脉也。伏行而濡于骨髓。故骨髓不濡。即肉不着骨。骨肉不相亲。即肉濡而却。肉濡而却。故齿长而枯。发无润泽。无润泽者。骨先死。戊日笃。己日死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gGafkMzQJbV', 4, '{"title":"第20100070条・二十四难","description":"<p>2、足太阴气绝。则脉不营其口唇。口唇者。肌肉之本也。脉不营。则肌肉不滑泽。肌肉不滑泽。则人中满。人中满。则唇反。唇反。则肉先死。甲日笃。乙日死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100070,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、足太阴气绝。则脉不营其口唇。口唇者。肌肉之本也。脉不营。则肌肉不滑泽。肌肉不滑泽。则人中满。人中满。则唇反。唇反。则肉先死。甲日笃。乙日死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6d6dsJIs1Kx', 4, '{"title":"第20100071条・二十四难","description":"<p>3、足厥阴气绝。即筋缩引卵与舌卷。厥阴者。肝脉也。肝者。筋之合也。筋者。聚于阴器而络于舌本。故脉不营。则筋缩急。即引卵与舌。故舌卷卵缩。此筋先死。庚日笃。辛日死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100071,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '3、足厥阴气绝。即筋缩引卵与舌卷。厥阴者。肝脉也。肝者。筋之合也。筋者。聚于阴器而络于舌本。故脉不营。则筋缩急。即引卵与舌。故舌卷卵缩。此筋先死。庚日笃。辛日死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('45KM5aGFP2R', 4, '{"title":"第20100072条・二十四难","description":"<p>4、手太阴气绝。即皮毛焦。太阴者。肺也。行气温于皮毛者也。气弗营。则皮毛焦。皮毛焦。则津液去。津液去。则皮节伤。皮节伤。则皮枯毛折。毛折者。则毛先死。丙日笃。丁日死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100072,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '4、手太阴气绝。即皮毛焦。太阴者。肺也。行气温于皮毛者也。气弗营。则皮毛焦。皮毛焦。则津液去。津液去。则皮节伤。皮节伤。则皮枯毛折。毛折者。则毛先死。丙日笃。丁日死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RbypAeDtcwW', 4, '{"title":"第20100073条・二十四难","description":"<p>5、手少阴气绝。则脉不通。脉不通。则血不流。血不流。则色泽去。故面色黑如黧。此血先死。壬日笃。癸日死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100073,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '5、手少阴气绝。则脉不通。脉不通。则血不流。血不流。则色泽去。故面色黑如黧。此血先死。壬日笃。癸日死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uloKYm6W8jd', 4, '{"title":"第20100074条・二十四难","description":"<p>6、三阴气俱绝者。则目眩转。目瞑。目瞑者。为失志。失志者。则志先死。死即$l{一本作则}目瞑也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100074,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '6、三阴气俱绝者。则目眩转。目瞑。目瞑者。为失志。失志者。则志先死。死即$l{一本作则}目瞑也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pxtOiTINy68', 4, '{"title":"第20100075条・二十四难","description":"<p>7、六阳气俱绝者。则阴与阳相离。阴阳相离。则腠理泄。绝汗乃出。大如贯珠。转出不流。即气先死。旦占夕死。夕占旦死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100075,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '7、六阳气俱绝者。则阴与阳相离。阴阳相离。则腠理泄。绝汗乃出。大如贯珠。转出不流。即气先死。旦占夕死。夕占旦死。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bGPZEXjn6pa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JW4huKhxCQR', 4, '{"title":"第20100076条・二十五难","description":"<p>1、曰。有十二经。五脏六腑十一耳。其一经者。何等经也。然。一经者。手少阴与心主别脉也。心主与三焦为表里。俱有名而无形。故言经有十二也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100076,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。有十二经。五脏六腑十一耳。其一经者。何等经也。然。一经者。手少阴与心主别脉也。心主与三焦为表里。俱有名而无形。故言经有十二也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '6LIiawVrQfT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0D2QZ6WY5No', 4, '{"title":"第20100077条・二十六难","description":"<p>1、曰。经有十二。络有十五。余三络者。是何等络也。然。有阳络。有阴络。有脾之大络。阳络者。阳跷之络也。阴络者。阴跷之络也。故络有十五焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100077,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。经有十二。络有十五。余三络者。是何等络也。然。有阳络。有阴络。有脾之大络。阳络者。阳跷之络也。阴络者。阴跷之络也。故络有十五焉。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'eezbSxnIJv9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zXz0Lh6iR5n', 4, '{"title":"第20100078条・二十七难","description":"<p>1、曰。脉有奇经八脉者。不拘于十二经。何也。然。有阳维。有阴维。有阳跷。有阴跷。有冲。有督。有任。有带之脉。凡此八脉者。皆不拘于经。故曰奇经八脉也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100078,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。脉有奇经八脉者。不拘于十二经。何也。然。有阳维。有阴维。有阳跷。有阴跷。有冲。有督。有任。有带之脉。凡此八脉者。皆不拘于经。故曰奇经八脉也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'aTMz8jofExQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mW5mVpVMkaF', 4, '{"title":"第20100079条・二十七难","description":"<p>2、经有十二。络有十五。凡二十七。气相随上下。何独不拘于经也。然。圣人图设沟渠。通利水道。以备不虞。天雨降下。沟渠溢满。当此之时。留需妄行。圣人不能复图也。此络脉满溢。诸经不能复拘也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100079,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、经有十二。络有十五。凡二十七。气相随上下。何独不拘于经也。然。圣人图设沟渠。通利水道。以备不虞。天雨降下。沟渠溢满。当此之时。留需妄行。圣人不能复图也。此络脉满溢。诸经不能复拘也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'aTMz8jofExQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FpRSCFPpR2O', 4, '{"title":"第20100080条・二十八难","description":"<p>1、曰。其奇经八脉者。既不拘于十二经。皆何起何继也。然。督脉者。起于下极之俞。并于脊里。上至风府。入属于脑。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100080,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。其奇经八脉者。既不拘于十二经。皆何起何继也。然。督脉者。起于下极之俞。并于脊里。上至风府。入属于脑。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zqAet1Ip4lJ', 4, '{"title":"第20100081条・二十八难","description":"<p>2、任脉者。起于中极之下。以上毛际。循腹里。上关元。至咽喉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100081,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、任脉者。起于中极之下。以上毛际。循腹里。上关元。至咽喉。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('22ZKuYDALPn', 4, '{"title":"第20100082条・二十八难","description":"<p>3、冲脉者。起于气冲。并足阳明之经。夹脐上行。至胸中而散也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100082,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '3、冲脉者。起于气冲。并足阳明之经。夹脐上行。至胸中而散也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hmr6mk22V5T', 4, '{"title":"第20100083条・二十八难","description":"<p>4、带脉者。起于季胁。回身一周。阳跷脉者。起于跟中。循外踝上行。入风池。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100083,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '4、带脉者。起于季胁。回身一周。阳跷脉者。起于跟中。循外踝上行。入风池。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xo1eAU4fVfp', 4, '{"title":"第20100084条・二十八难","description":"<p>5、阴跷脉者。亦起于跟中。循内踝上行。至咽喉。交贯冲脉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100084,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '5、阴跷脉者。亦起于跟中。循内踝上行。至咽喉。交贯冲脉。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mvWjvqtPk6d', 4, '{"title":"第20100085条・二十八难","description":"<p>6、阳维。阴维者。维络于身。溢蓄。不能环流灌溉诸经者也。故阳维起于诸阳会也。阴维起于诸阴交也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100085,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '6、阳维。阴维者。维络于身。溢蓄。不能环流灌溉诸经者也。故阳维起于诸阳会也。阴维起于诸阴交也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JCGhgYDPcww', 4, '{"title":"第20100086条・二十八难","description":"<p>7、比于圣人图设沟渠。沟渠满溢。流于深湖。故圣人不能拘通也。而人脉隆盛。入于八脉。而不还周。故十二经亦有不能拘之。其受邪气。畜则肿热。砭射之也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100086,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '7、比于圣人图设沟渠。沟渠满溢。流于深湖。故圣人不能拘通也。而人脉隆盛。入于八脉。而不还周。故十二经亦有不能拘之。其受邪气。畜则肿热。砭射之也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uMrlcTQ2VEC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iE287XpeS25', 4, '{"title":"第20100087条・二十九难","description":"<p>1、曰。奇经之为病。何如。然。阳维维于阳。阴维维于阴。阴阳不能自相维。则怅然失志。溶溶不能自收持。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100087,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。奇经之为病。何如。然。阳维维于阳。阴维维于阴。阴阳不能自相维。则怅然失志。溶溶不能自收持。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('whhaIvpECnA', 4, '{"title":"第20100088条・二十九难","description":"<p>2、阳维为病苦寒热。阴维为病若心痛。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100088,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2、阳维为病苦寒热。阴维为病若心痛。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MJpHKQ9qqvD', 4, '{"title":"第20100089条・二十九难","description":"<p>3、阴跷为病。阳缓而阴急。阳跷为病。阴缓而阳急。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100089,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '3、阴跷为病。阳缓而阴急。阳跷为病。阴缓而阳急。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TANAxRhmmDN', 4, '{"title":"第20100090条・二十九难","description":"<p>4、冲之为病。逆气而里急。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100090,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '4、冲之为病。逆气而里急。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R2Q303D3c01', 4, '{"title":"第20100091条・二十九难","description":"<p>5、督之为病。脊强而厥。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100091,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '5、督之为病。脊强而厥。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3P66IygXUrD', 4, '{"title":"第20100092条・二十九难","description":"<p>6、任之为病。其内苦结。男子为七疝。妇子为瘕聚。带之为病。腹满。腰溶溶若坐水中。此奇经八脉之为病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100092,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '6、任之为病。其内苦结。男子为七疝。妇子为瘕聚。带之为病。腹满。腰溶溶若坐水中。此奇经八脉之为病也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zaVSlZl8BHq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('08kCueG8gHA', 4, '{"title":"第20100093条・三十难","description":"<p>1、曰。营气之行。常与卫气相随不。然。经言人受气于谷。谷入于胃。乃传于五脏六腑。五脏六腑皆受于气。其清者为营。浊者为卫。荣行脉中。卫行脉外。营周不息。五十而复大会。阴阳相贯。如环之无端。故知营卫相随也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100093,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '2024-09-26T13:56:09.000Z', '1、曰。营气之行。常与卫气相随不。然。经言人受气于谷。谷入于胃。乃传于五脏六腑。五脏六腑皆受于气。其清者为营。浊者为卫。荣行脉中。卫行脉外。营周不息。五十而复大会。阴阳相贯。如环之无端。故知营卫相随也。', '2024-09-26T13:56:09.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'lr26ABcpIfP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XiRxtBsYOQb', 4, '{"title":"第20100094条・三十一难","description":"<p>1、曰。三焦者。何禀何生。何始何终。其治常在何许。可晓以不。然。三焦者。水谷之道路。气之所终始也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100094,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。三焦者。何禀何生。何始何终。其治常在何许。可晓以不。然。三焦者。水谷之道路。气之所终始也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cz2SzBVizNw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eegzeaXC9TW', 4, '{"title":"第20100095条・三十一难","description":"<p>2、上焦者。在心下。下膈。在胃上口。主内而不出。其治在膻中。玉堂下一寸六分。直两乳间陷者是。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100095,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2、上焦者。在心下。下膈。在胃上口。主内而不出。其治在膻中。玉堂下一寸六分。直两乳间陷者是。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cz2SzBVizNw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5mu8qhYC83v', 4, '{"title":"第20100096条・三十一难","description":"<p>3、中焦者。在胃中脘。不上不下。主腐熟水谷。其治在脐傍。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100096,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '3、中焦者。在胃中脘。不上不下。主腐熟水谷。其治在脐傍。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cz2SzBVizNw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wj8sakYwG0j', 4, '{"title":"第20100097条・三十一难","description":"<p>4、下焦者。当膀胱上口。主分别清浊。主出而不内。以传导也。其治在脐下一寸。故名曰三焦。其府在气街。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100097,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '4、下焦者。当膀胱上口。主分别清浊。主出而不内。以传导也。其治在脐下一寸。故名曰三焦。其府在气街。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cz2SzBVizNw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Jjm97wuI35', 4, '{"title":"第20100098条・三十二难","description":"<p>1、曰。五脏俱等。而心肺独在鬲上者。何也。然。心者血。肺者气。血为荣。气为卫。相随上下。谓之荣卫。通行经络。营周于外。故令心肺独在鬲上也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100098,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏俱等。而心肺独在鬲上者。何也。然。心者血。肺者气。血为荣。气为卫。相随上下。谓之荣卫。通行经络。营周于外。故令心肺独在鬲上也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Jk6imqoa25A');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jCxgnp0WXtN', 4, '{"title":"第20100099条・三十三难","description":"<p>1、曰。肝青象木。肺白象金。肝得水而沉。木得水而浮。肺得水而浮。金得水而沉。其意何也。然。肝者。非为纯木也。乙角也。庚之柔。大言阴与阳。小言夫与妇。释其微阳。而吸其微阴之气。其意乐金。又行阴道多。故令肝得水而沉也。肺者。非为纯金也。辛商也。丙之柔。大言阴与阳。小言夫与妇。释其微阴。婚而就火。其意乐火。又行阳道多。故令肺得水而浮也。肺熟而复沉。肝熟而复浮者。何也。故知辛当归庚。乙当归甲也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100099,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。肝青象木。肺白象金。肝得水而沉。木得水而浮。肺得水而浮。金得水而沉。其意何也。然。肝者。非为纯木也。乙角也。庚之柔。大言阴与阳。小言夫与妇。释其微阳。而吸其微阴之气。其意乐金。又行阴道多。故令肝得水而沉也。肺者。非为纯金也。辛商也。丙之柔。大言阴与阳。小言夫与妇。释其微阴。婚而就火。其意乐火。又行阳道多。故令肺得水而浮也。肺熟而复沉。肝熟而复浮者。何也。故知辛当归庚。乙当归甲也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'hmTJWk4UeKC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O7Zxke7flEc', 4, '{"title":"第20100100条・三十四难","description":"<p>1、曰。五脏各有声。色。臭。味。液。皆可晓知以不。然。《十变》言。肝色青。其臭臊。其味酸。其声呼。其液泣。心色赤。其臭焦。其味苦。其声言。其液汗。脾色黄。其臭香。其味甘。其声歌。其液涎。肺色白。其臭腥。其味辛。其声哭。其液涕。肾色黑。其臭腐。其味咸。其声呻。其液唾。是五脏声。色。臭。味。液也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100100,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏各有声。色。臭。味。液。皆可晓知以不。然。《十变》言。肝色青。其臭臊。其味酸。其声呼。其液泣。心色赤。其臭焦。其味苦。其声言。其液汗。脾色黄。其臭香。其味甘。其声歌。其液涎。肺色白。其臭腥。其味辛。其声哭。其液涕。肾色黑。其臭腐。其味咸。其声呻。其液唾。是五脏声。色。臭。味。液也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Awk3SX2JsDZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fplf0qxhYgH', 4, '{"title":"第20100101条・三十四难","description":"<p>2、五脏有七神。各何所藏那。然。脏者。人之神气所舍藏也。故肝藏魂。肺藏魄。心藏神。脾藏意与智。肾藏精与志也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2、五脏有七神。各何所藏那。然。脏者。人之神气所舍藏也。故肝藏魂。肺藏魄。心藏神。脾藏意与智。肾藏精与志也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Awk3SX2JsDZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tA5XhTF8VGn', 4, '{"title":"第20100102条・三十五难","description":"<p>1、曰。五脏各有所腑皆相近。而心。肺独去大肠。小肠远者。何谓$l{一本无谓字}也。然。经言心营。肺卫。通行阳气。故居在上。大肠。小肠。传阴气而下。故居在下。所以相去而远也。又诸腑皆阳也。清净之处。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏各有所腑皆相近。而心。肺独去大肠。小肠远者。何谓$l{一本无谓字}也。然。经言心营。肺卫。通行阳气。故居在上。大肠。小肠。传阴气而下。故居在下。所以相去而远也。又诸腑皆阳也。清净之处。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cuyMHI0sHsn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('12aRqC2gIMo', 4, '{"title":"第20100103条・三十五难","description":"<p>2、今大肠。小肠。胃与膀胱。皆受不净。其意何也。然。诸腑者。谓是非也。经言。小肠者。受盛之腑也。大肠者。传泻行道之腑也。胆者。清净之腑也。胃者。水谷之腑也。膀胱者。津液之腑也。一腑犹无两名。故知非也。小肠者。心之腑。大肠者。肺之腑。胆者。肝之腑。胃者。脾之腑。膀胱者。肾之腑。小肠谓赤肠。大肠谓白肠。胆者谓青肠。胃者谓黄肠。膀胱者谓黑肠。下焦之所治也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100103,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2、今大肠。小肠。胃与膀胱。皆受不净。其意何也。然。诸腑者。谓是非也。经言。小肠者。受盛之腑也。大肠者。传泻行道之腑也。胆者。清净之腑也。胃者。水谷之腑也。膀胱者。津液之腑也。一腑犹无两名。故知非也。小肠者。心之腑。大肠者。肺之腑。胆者。肝之腑。胃者。脾之腑。膀胱者。肾之腑。小肠谓赤肠。大肠谓白肠。胆者谓青肠。胃者谓黄肠。膀胱者谓黑肠。下焦之所治也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'cuyMHI0sHsn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SfMW9yoot1E', 4, '{"title":"第20100104条・三十六难","description":"<p>1、曰。脏各有一耳。肾独有两者。何也。然。肾两者。非皆肾也。其左者为肾。右者为命门。命门者。诸神精之所舍。原气之所系也。男子以藏精。女子以系胞。故知肾有一也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100104,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。脏各有一耳。肾独有两者。何也。然。肾两者。非皆肾也。其左者为肾。右者为命门。命门者。诸神精之所舍。原气之所系也。男子以藏精。女子以系胞。故知肾有一也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Q0wtzaZhQxF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GDTmuJUF517', 4, '{"title":"第20100105条・三十七难","description":"<p>1、曰。五脏之气。于何发起。通于何许。可晓以不。然。五脏者。常内阅于上七窍也。故肺气通于鼻。鼻和则知香臭矣。肝气通于目。目和则知黑白矣。脾气通于口。口和则知谷味矣。心气通于舌。舌和则知五味矣。肾气通于耳。耳和则知五音矣。五脏不和。则七窍不通。六腑不和。则留结为痈。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。五脏之气。于何发起。通于何许。可晓以不。然。五脏者。常内阅于上七窍也。故肺气通于鼻。鼻和则知香臭矣。肝气通于目。目和则知黑白矣。脾气通于口。口和则知谷味矣。心气通于舌。舌和则知五味矣。肾气通于耳。耳和则知五音矣。五脏不和。则七窍不通。六腑不和。则留结为痈。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'CcKl1cAMmUl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dvJsxArFOjv', 4, '{"title":"第20100106条・三十七难","description":"<p>2、邪在六腑。则阳脉不和。阳脉不和。则气留之。气留之。则阳脉盛矣。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2、邪在六腑。则阳脉不和。阳脉不和。则气留之。气留之。则阳脉盛矣。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'CcKl1cAMmUl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FcvM8Wcy7gX', 4, '{"title":"第20100107条・三十七难","description":"<p>3、邪在五腑。则阴脉不和。阴脉不和。则血留之。血留之。则阴脉盛矣。阴气太盛。则阳气不得相营也。故曰格。阳气太盛。则阴气不得相营也。故曰关。阴阳俱盛。不得相营也。故曰关格。关格者。不得尽其命而死矣。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '3、邪在五腑。则阴脉不和。阴脉不和。则血留之。血留之。则阴脉盛矣。阴气太盛。则阳气不得相营也。故曰格。阳气太盛。则阴气不得相营也。故曰关。阴阳俱盛。不得相营也。故曰关格。关格者。不得尽其命而死矣。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'CcKl1cAMmUl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XCKj66uvl3i', 4, '{"title":"第20100108条・三十七难","description":"<p>4、经言气独行于五脏。不营于六腑者。何也。然。夫气之所行也。如水之流。不得息也。故阴脉营于五脏。阳脉营于六腑。如环无端。莫知其纪。终而复始。其不覆溢。人气内温于脏腑。外濡于凑理。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100108,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '4、经言气独行于五脏。不营于六腑者。何也。然。夫气之所行也。如水之流。不得息也。故阴脉营于五脏。阳脉营于六腑。如环无端。莫知其纪。终而复始。其不覆溢。人气内温于脏腑。外濡于凑理。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'CcKl1cAMmUl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t4GO1Zf0SGP', 4, '{"title":"第20100109条・三十八难","description":"<p>1、曰。脏唯有五。腑独有六者。何也。然。所以腑有六者。谓三焦也。有原气之别焉。主持诸气。有名而无形。其经$l{一本无经字}属手少阳。此外腑也。故言腑有六焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100109,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。脏唯有五。腑独有六者。何也。然。所以腑有六者。谓三焦也。有原气之别焉。主持诸气。有名而无形。其经$l{一本无经字}属手少阳。此外腑也。故言腑有六焉。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'K9dbKTLq4nt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SyRjL15UJ6S', 4, '{"title":"第20100110条・三十九难","description":"<p>1、曰。经言腑有五。脏有六者。何也。然。六腑者。正有五腑也。五脏亦有六脏者。谓肾有两脏也。其左为肾。右为命门。命门者。谓精神之所舍也。男子以藏精。女子以系胞。其气与肾通。故言脏有六也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100110,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。经言腑有五。脏有六者。何也。然。六腑者。正有五腑也。五脏亦有六脏者。谓肾有两脏也。其左为肾。右为命门。命门者。谓精神之所舍也。男子以藏精。女子以系胞。其气与肾通。故言脏有六也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5Lx1ncampL0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ctTA6N6bZnI', 4, '{"title":"第20100111条・三十九难","description":"<p>2、腑有五者。何也。然。五脏各一腑。三焦亦是一腑。然不属于五脏。故言腑有五焉。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100111,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2、腑有五者。何也。然。五脏各一腑。三焦亦是一腑。然不属于五脏。故言腑有五焉。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5Lx1ncampL0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZFnqk3PWA3f', 4, '{"title":"第20100112条・四十难","description":"<p>1、曰。经言。肝主色。心主臭。脾主味。肺主声。肾主液。鼻者。肺之候。而反知香臭。耳者。肾之候。而反闻声。其意何也。然。肺者。西方金也。金生于巳。巳者南方火。火者心。心主臭。故令鼻知香臭。肾者。北方水也。水生于申。申者西方金。金者肺。肺主声。故令耳闻声。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100112,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。经言。肝主色。心主臭。脾主味。肺主声。肾主液。鼻者。肺之候。而反知香臭。耳者。肾之候。而反闻声。其意何也。然。肺者。西方金也。金生于巳。巳者南方火。火者心。心主臭。故令鼻知香臭。肾者。北方水也。水生于申。申者西方金。金者肺。肺主声。故令耳闻声。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Ek2BOybp1AR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vrx8YunRav4', 4, '{"title":"第20100113条・四十一难","description":"<p>1、曰。肝独有两叶。以何应也。然。肝者。东方木也。木者。春也。万物始生。其尚幼小。意无所亲。去太阴尚近。离太阳不远。犹有两心。故有两叶。亦应木叶也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100113,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '2024-09-26T13:56:10.000Z', '1、曰。肝独有两叶。以何应也。然。肝者。东方木也。木者。春也。万物始生。其尚幼小。意无所亲。去太阴尚近。离太阳不远。犹有两心。故有两叶。亦应木叶也。', '2024-09-26T13:56:10.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '3cOAMkyhkdK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jkp1YMx2lrB', 4, '{"title":"第20100114条・四十二难","description":"<p>1、曰。人肠胃长短。受水谷多少。各几何。然。胃大一尺五寸。径五寸。长二尺六寸。横屈。受水谷三斗五升。其中常留谷二斗。水一斗五升。小肠大二寸半。径八分。分之少半。长三丈二尺。受谷二斗四升。水六升三合。合之大半。回肠大四寸。径一寸半。长二丈一尺。受谷一斗。水七升半。广肠大八寸。径二寸半。长二尺八寸。受谷九升三合。八分合之一。故肠胃凡长五丈八尺四寸。合受水谷八斗七升六合。八分合之一。此肠胃长短。受水谷之数也。肝重四斤四两。左三叶。右四叶。凡七叶。主藏魂。心重十二两。中有七孔三毛。盛精汁三合。主藏神。脾重二斤三两。扁广三寸。长五寸。有散膏半斤。主裹血。温五脏。主藏意。肺重三斤三两。六叶两耳。凡八叶。主藏魄。肾有两枚。重一斤一两。主藏志。胆在肝之短叶间。重三两三铢。盛精汁三合。胃重二斤一两$l{一本作二斤二两，《史记正义》作二斤十四两，多本从此}。纡曲屈伸。长二尺六寸。大一尺五寸。径五寸。盛谷二斗。水一斗五升。小肠重二斤十四两。长三丈二尺。广二寸半。径八分。分之少半。左回叠积十六曲。盛谷二斗四升。水六升三合。合之大半。大肠重二斤十二两。长二丈一尺。广四寸。径一寸。当脐右回十六曲。盛谷一斗。水七升半。膀胱重九两二铢。纵广九寸。盛溺九升九合。口广二寸半。唇至齿长九分。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十二两$l{《灵枢·肠胃》：咽门重十两，多本从之}。广二寸半。至胃长一尺六寸。喉咙重十二两。广二寸。长一尺二寸。九节。肛门重十二两。大八寸。径二寸大半。长二尺八寸。受谷九升三合。八分合之一。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100114,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人肠胃长短。受水谷多少。各几何。然。胃大一尺五寸。径五寸。长二尺六寸。横屈。受水谷三斗五升。其中常留谷二斗。水一斗五升。小肠大二寸半。径八分。分之少半。长三丈二尺。受谷二斗四升。水六升三合。合之大半。回肠大四寸。径一寸半。长二丈一尺。受谷一斗。水七升半。广肠大八寸。径二寸半。长二尺八寸。受谷九升三合。八分合之一。故肠胃凡长五丈八尺四寸。合受水谷八斗七升六合。八分合之一。此肠胃长短。受水谷之数也。肝重四斤四两。左三叶。右四叶。凡七叶。主藏魂。心重十二两。中有七孔三毛。盛精汁三合。主藏神。脾重二斤三两。扁广三寸。长五寸。有散膏半斤。主裹血。温五脏。主藏意。肺重三斤三两。六叶两耳。凡八叶。主藏魄。肾有两枚。重一斤一两。主藏志。胆在肝之短叶间。重三两三铢。盛精汁三合。胃重二斤一两$l{一本作二斤二两，《史记正义》作二斤十四两，多本从此}。纡曲屈伸。长二尺六寸。大一尺五寸。径五寸。盛谷二斗。水一斗五升。小肠重二斤十四两。长三丈二尺。广二寸半。径八分。分之少半。左回叠积十六曲。盛谷二斗四升。水六升三合。合之大半。大肠重二斤十二两。长二丈一尺。广四寸。径一寸。当脐右回十六曲。盛谷一斗。水七升半。膀胱重九两二铢。纵广九寸。盛溺九升九合。口广二寸半。唇至齿长九分。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十二两$l{《灵枢·肠胃》：咽门重十两，多本从之}。广二寸半。至胃长一尺六寸。喉咙重十二两。广二寸。长一尺二寸。九节。肛门重十二两。大八寸。径二寸大半。长二尺八寸。受谷九升三合。八分合之一。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'LZ6KJ3sAjv4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Na8xKi2GBwh', 4, '{"title":"第20100115条・四十三难","description":"<p>1、曰。人不食饮。七日而死者。何也。然。人胃中当留谷二斗。水一斗五升。故平人日再至圊。一行二升半。一日中五升。七日五七三斗五升。而水谷尽矣。故平人不食饮七日而死者。水谷津液俱尽。即死矣。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100115,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人不食饮。七日而死者。何也。然。人胃中当留谷二斗。水一斗五升。故平人日再至圊。一行二升半。一日中五升。七日五七三斗五升。而水谷尽矣。故平人不食饮七日而死者。水谷津液俱尽。即死矣。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'MJOf7WN16tu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CczPD0CgAu2', 4, '{"title":"第20100116条・四十四难","description":"<p>1、曰。七冲门何在。然。唇为飞门。齿为户门。会厌为吸门。胃为贲门。太仓下口为幽门。大肠小肠会为阑门。下极为魄门。故曰七冲门也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100116,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。七冲门何在。然。唇为飞门。齿为户门。会厌为吸门。胃为贲门。太仓下口为幽门。大肠小肠会为阑门。下极为魄门。故曰七冲门也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'VDcKULw3sFC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pIWAIAMOUOJ', 4, '{"title":"第20100117条・四十五难","description":"<p>1、曰。经言八会者。何也。然。腑会太仓。脏会季胁。筋会阳陵泉。髓会绝骨。血会鬲俞。骨会大抒。脉会太渊。气会三焦外。一筋直两乳内也。热病在内者。取其会之气穴也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100117,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。经言八会者。何也。然。腑会太仓。脏会季胁。筋会阳陵泉。髓会绝骨。血会鬲俞。骨会大抒。脉会太渊。气会三焦外。一筋直两乳内也。热病在内者。取其会之气穴也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'q055Qp9ZT8u');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pDmBk2pRg1c', 4, '{"title":"第20100118条・四十六难","description":"<p>1、曰。老人卧而不寐。少壮寐而不寤者。何也。然。经言少壮者。血气盛。肌肉滑。气道通。营卫之行不失于常。故昼日精。夜不寤也。老人血气衰。肌肉不滑。营卫之道涩。故昼日不能精。夜不得寐也。故知老人不得寐也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100118,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。老人卧而不寐。少壮寐而不寤者。何也。然。经言少壮者。血气盛。肌肉滑。气道通。营卫之行不失于常。故昼日精。夜不寤也。老人血气衰。肌肉不滑。营卫之道涩。故昼日不能精。夜不得寐也。故知老人不得寐也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4K6bbC3V16i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CJfJhTwHMft', 4, '{"title":"第20100119条・四十七难","description":"<p>1、曰。人面独能耐寒者。何也。然。人头者。诸阳之会也。诸阴脉皆至颈。胸中而还。独诸阳脉皆上至头耳。故令面耐寒也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100119,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人面独能耐寒者。何也。然。人头者。诸阳之会也。诸阴脉皆至颈。胸中而还。独诸阳脉皆上至头耳。故令面耐寒也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '2swGBP8bcfM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WRdwoaq9Pdc', 4, '{"title":"第20100120条・四十八难","description":"<p>1、曰。人有三虚三实。何谓也。然。有脉之虚实。有病之虚实。有诊之虚实也。脉之虚实者。濡者为虚。牢者为实。病之虚实者。出者为虚。入者为实。言者为虚。不言者为实。缓者为虚。急者为实。诊之虚实者。痒者为虚。痛者为实。外痛内快。为外实内虚。内痛外快。为内实外虚。故曰虚实也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100120,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。人有三虚三实。何谓也。然。有脉之虚实。有病之虚实。有诊之虚实也。脉之虚实者。濡者为虚。牢者为实。病之虚实者。出者为虚。入者为实。言者为虚。不言者为实。缓者为虚。急者为实。诊之虚实者。痒者为虚。痛者为实。外痛内快。为外实内虚。内痛外快。为内实外虚。故曰虚实也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'ItnpIk9Lezi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UKrszdjsVE5', 4, '{"title":"第20100121条・四十九难","description":"<p>1、曰。有正经自病。有五邪所伤。何以别之。然。经言忧愁思虑则伤心。形寒饮冷则伤肺。恚怒气逆。上而不下则伤肝。饮食劳倦则伤脾。久坐湿地。强力入水则伤肾。是正经之自病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100121,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。有正经自病。有五邪所伤。何以别之。然。经言忧愁思虑则伤心。形寒饮冷则伤肺。恚怒气逆。上而不下则伤肝。饮食劳倦则伤脾。久坐湿地。强力入水则伤肾。是正经之自病也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Iu45y7YJfFQ', 4, '{"title":"第20100122条・四十九难","description":"<p>2、何谓五邪。然。有中风。有伤暑。有饮食劳倦。有伤寒。有中湿。此之谓五邪。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100122,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2、何谓五邪。然。有中风。有伤暑。有饮食劳倦。有伤寒。有中湿。此之谓五邪。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sD3I6LS3H5N', 4, '{"title":"第20100123条・四十九难","description":"<p>3、假令心病。何以知中风得之。然。其色当赤。何以言之。肝主色。自入为青。入心为赤。入脾为黄。入肺为白。入肾为黑。肝为心邪。故知当赤色。其病身热。胁下满痛。其脉浮大而弦。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100123,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '3、假令心病。何以知中风得之。然。其色当赤。何以言之。肝主色。自入为青。入心为赤。入脾为黄。入肺为白。入肾为黑。肝为心邪。故知当赤色。其病身热。胁下满痛。其脉浮大而弦。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zK6iH5hR7mS', 4, '{"title":"第20100124条・四十九难","description":"<p>4、何以知伤暑得之。然。当恶焦臭。何以言之。心主臭。自入为焦臭。入脾为香臭。入肝为臊臭。入肾为腐臭。入肺为腥臭。故知心病伤暑得之。当恶焦臭。其病身热而烦。心痛。其脉浮大而散。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100124,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '4、何以知伤暑得之。然。当恶焦臭。何以言之。心主臭。自入为焦臭。入脾为香臭。入肝为臊臭。入肾为腐臭。入肺为腥臭。故知心病伤暑得之。当恶焦臭。其病身热而烦。心痛。其脉浮大而散。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BRtgprqTcli', 4, '{"title":"第20100125条・四十九难","description":"<p>5、何以知饮食劳倦得之。然。当喜苦味也。何以言之。脾主味。入肝为酸。人心为苦。入肺为辛。入肾为咸。自入为甘。故知脾邪入心。为喜苦味也。其病身热而体重。嗜卧。四肢不收。其脉浮大而缓。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100125,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '5、何以知饮食劳倦得之。然。当喜苦味也。何以言之。脾主味。入肝为酸。人心为苦。入肺为辛。入肾为咸。自入为甘。故知脾邪入心。为喜苦味也。其病身热而体重。嗜卧。四肢不收。其脉浮大而缓。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xJsq5lp4Z1S', 4, '{"title":"第20100126条・四十九难","description":"<p>6、何以知伤寒得之。然。当谵言妄语。何以言之。肺主声。入肝为呼。入心为言。入脾为歌。入肾为呻。自入为哭。故知肺邪入心。为谵言妄语也。其病身热。洒洒恶寒。甚则喘咳。其脉浮大而涩。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100126,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '6、何以知伤寒得之。然。当谵言妄语。何以言之。肺主声。入肝为呼。入心为言。入脾为歌。入肾为呻。自入为哭。故知肺邪入心。为谵言妄语也。其病身热。洒洒恶寒。甚则喘咳。其脉浮大而涩。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XMYLqAxZHMV', 4, '{"title":"第20100127条・四十九难","description":"<p>7、何以知中湿得之。然。当喜汗出不可止。何以言之。肾主液。入肝为泣。入心为汗。入脾为涎。入肺为涕。自入为唾。故知肾邪入心。为汗出不可止也。其病身热。而小腹痛。足胫寒而逆。其脉沉濡而大。此五邪之法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100127,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '7、何以知中湿得之。然。当喜汗出不可止。何以言之。肾主液。入肝为泣。入心为汗。入脾为涎。入肺为涕。自入为唾。故知肾邪入心。为汗出不可止也。其病身热。而小腹痛。足胫寒而逆。其脉沉濡而大。此五邪之法也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'zhTqJFN0qAb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4JNpwT3xElJ', 4, '{"title":"第20100128条・五十难","description":"<p>1、曰。病有虚邪。有实邪。有贼邪。有微邪。有正邪。何以别之。然。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。何以言之。假令心病。中风得之为虚邪。伤暑得之为正邪。饮食劳倦得之为实邪。伤寒得之为微邪。中湿得之为贼邪。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100128,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。病有虚邪。有实邪。有贼邪。有微邪。有正邪。何以别之。然。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。何以言之。假令心病。中风得之为虚邪。伤暑得之为正邪。饮食劳倦得之为实邪。伤寒得之为微邪。中湿得之为贼邪。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '53piW7vYaxn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AZsRTMfsB16', 4, '{"title":"第20100129条・五十一难","description":"<p>1、曰。病有欲得温者。有欲得寒者。有欲得见人者。有不欲得见人者。而各不同。病在何脏腑也。然。病欲得寒。而欲见人者。病在腑也。病欲得温。而不欲见人者。病在脏也。何以言之。腑者阳也。阳病欲得寒。又欲见人。脏者。阴也。阴病欲得温。又欲闭户独处。恶闻人声。故以别知脏腑之病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100129,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。病有欲得温者。有欲得寒者。有欲得见人者。有不欲得见人者。而各不同。病在何脏腑也。然。病欲得寒。而欲见人者。病在腑也。病欲得温。而不欲见人者。病在脏也。何以言之。腑者阳也。阳病欲得寒。又欲见人。脏者。阴也。阴病欲得温。又欲闭户独处。恶闻人声。故以别知脏腑之病也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '7nDnTOvxTDA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KkilmHKyR48', 4, '{"title":"第20100130条・五十二难","description":"<p>1、曰。脏腑发病。根本等不。然。不等也。其不等奈何。然。脏病者。止而不移。其病不离其处。腑病者。仿佛贲响。上下行流。居处无常。故以此知脏腑根本不同也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100130,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '2024-09-26T13:56:11.000Z', '1、曰。脏腑发病。根本等不。然。不等也。其不等奈何。然。脏病者。止而不移。其病不离其处。腑病者。仿佛贲响。上下行流。居处无常。故以此知脏腑根本不同也。', '2024-09-26T13:56:11.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'bmdgqx8u8mn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AdrV8XHDYam', 4, '{"title":"第20100131条・五十三难","description":"<p>1、曰。经言七传者死。间脏者生。何谓也。然。七传者。传其所胜也。间脏者。传其子也。何以言之。假令心病传肺。肺传肝。肝传脾。脾传肾。肾传心。一脏不再伤。故言七传者死也。间脏者。传其所生也。假令心病传脾。脾传肺。肺传肾。肾传肝。肝传心。是母子相传。竟而复始。如环无端。故曰生也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100131,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。经言七传者死。间脏者生。何谓也。然。七传者。传其所胜也。间脏者。传其子也。何以言之。假令心病传肺。肺传肝。肝传脾。脾传肾。肾传心。一脏不再伤。故言七传者死也。间脏者。传其所生也。假令心病传脾。脾传肺。肺传肾。肾传肝。肝传心。是母子相传。竟而复始。如环无端。故曰生也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'tnZaX37rA82');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5fzZLreFJwx', 4, '{"title":"第20100132条・五十四难","description":"<p>1、曰。脏病难治。腑病易治。何谓也。然。脏病所以难治者。传其所胜也。腑病易治者。传其子也。与七传。间传同法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100132,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。脏病难治。腑病易治。何谓也。然。脏病所以难治者。传其所胜也。腑病易治者。传其子也。与七传。间传同法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uuLC5t8tL4i');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4h9ol1Pplq2', 4, '{"title":"第20100133条・五十五难","description":"<p>1、曰。病有积。有聚。何以别之。然。积者。阴气也。聚者。阳气也。故阴沉而伏。阳浮而动。气之所积。名曰积。气之所聚。名曰聚。故积者。五脏所生。聚者。六腑所成也。积者。阴气也。其始发有常处。其痛不离其部。上下有所终始。左右有所穷处。聚者。阳气也。其始发无根本。上下无所留止。其痛无常处谓之聚。故以是别知积聚也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100133,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。病有积。有聚。何以别之。然。积者。阴气也。聚者。阳气也。故阴沉而伏。阳浮而动。气之所积。名曰积。气之所聚。名曰聚。故积者。五脏所生。聚者。六腑所成也。积者。阴气也。其始发有常处。其痛不离其部。上下有所终始。左右有所穷处。聚者。阳气也。其始发无根本。上下无所留止。其痛无常处谓之聚。故以是别知积聚也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '3X5Y2KxQqIh');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3RmecGWr5cl', 4, '{"title":"第20100134条・五十六难","description":"<p>1、曰。五脏之积。各有名乎。以何月。何日得之。然。肝之积。名曰肥气。在左胁下。如覆杯。有头足。久不愈。令人发咳逆。疟。连岁不已。以季夏戊己日得之。何以言之。肺病传于肝。肝当传脾。脾季夏适王。王者不受邪。肝复欲还肺。肺不肯受。故留结为积。故知肥气以季夏戊己日得之。心之积。名曰伏梁。起脐上。大如臂。上至心下。久不愈。令人病烦心。以秋庚辛日得之。何以言之。肾病传心。心当传肺。肺以秋适王。王者不受邪。心复欲还肾。肾不肯受。故留结为积。故知伏梁以秋庚辛日得之。脾之积。名曰痞气。在胃脘。覆大如盘。久不愈。令人四肢不收。发黄疸。饮食不为肌肤。以冬壬癸日得之。何以言之。肝病传脾。脾当传肾。肾以冬适王。王者不受邪。脾复欲还肝。肝不肯受。故留结为积。故知痞气以冬壬癸日得之。肺之积。名曰息贲。在右胁下。覆大如杯。久不已。令人洒淅寒热。喘咳。发肺壅。以春甲乙日得之。何以言之。心病传肺。肺当传肝。肝以春适王。王者不受邪。肺复欲还心。心不肯受。故留结为积。故知息贲以春甲乙日得之。肾之积。名曰贲豚。发于少腹。上至心下。若豚状。或上或下无时。久不已。令人喘逆。骨痿少气。以夏丙丁日得之。何以言之。脾病传肾。肾当传心。心以夏适王。王者不受邪。肾复欲还脾。脾不肯受。故留结为积。故知贲豚以夏丙丁日得之。此五积之要法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100134,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。五脏之积。各有名乎。以何月。何日得之。然。肝之积。名曰肥气。在左胁下。如覆杯。有头足。久不愈。令人发咳逆。疟。连岁不已。以季夏戊己日得之。何以言之。肺病传于肝。肝当传脾。脾季夏适王。王者不受邪。肝复欲还肺。肺不肯受。故留结为积。故知肥气以季夏戊己日得之。心之积。名曰伏梁。起脐上。大如臂。上至心下。久不愈。令人病烦心。以秋庚辛日得之。何以言之。肾病传心。心当传肺。肺以秋适王。王者不受邪。心复欲还肾。肾不肯受。故留结为积。故知伏梁以秋庚辛日得之。脾之积。名曰痞气。在胃脘。覆大如盘。久不愈。令人四肢不收。发黄疸。饮食不为肌肤。以冬壬癸日得之。何以言之。肝病传脾。脾当传肾。肾以冬适王。王者不受邪。脾复欲还肝。肝不肯受。故留结为积。故知痞气以冬壬癸日得之。肺之积。名曰息贲。在右胁下。覆大如杯。久不已。令人洒淅寒热。喘咳。发肺壅。以春甲乙日得之。何以言之。心病传肺。肺当传肝。肝以春适王。王者不受邪。肺复欲还心。心不肯受。故留结为积。故知息贲以春甲乙日得之。肾之积。名曰贲豚。发于少腹。上至心下。若豚状。或上或下无时。久不已。令人喘逆。骨痿少气。以夏丙丁日得之。何以言之。脾病传肾。肾当传心。心以夏适王。王者不受邪。肾复欲还脾。脾不肯受。故留结为积。故知贲豚以夏丙丁日得之。此五积之要法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4L7cTPlx7JN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a5MfHpuBTsE', 4, '{"title":"第20100135条・五十七难","description":"<p>1、曰。泄凡有几。皆有名不。然。泄凡有五。其名不同。有胃泄。有脾泄。有大肠泄。有小肠泄。有大瘕泄。名曰后重。胃泄者。饮食不化。色黄。脾泄者。腹胀满。泄注。食即呕吐逆。大肠泄者。食已窘迫。大便色白。肠鸣切痛。小肠泄者。溲而便脓血。少腹痛。大瘕泄者。里急后重。数至圊而不能便。茎中痛。此五泄之要法也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100135,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。泄凡有几。皆有名不。然。泄凡有五。其名不同。有胃泄。有脾泄。有大肠泄。有小肠泄。有大瘕泄。名曰后重。胃泄者。饮食不化。色黄。脾泄者。腹胀满。泄注。食即呕吐逆。大肠泄者。食已窘迫。大便色白。肠鸣切痛。小肠泄者。溲而便脓血。少腹痛。大瘕泄者。里急后重。数至圊而不能便。茎中痛。此五泄之要法也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '5IhW81cQXaL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FC7W2qJE1Jl', 4, '{"title":"第20100136条・五十八难","description":"<p>1、曰。伤寒有几。其脉有变不。然。伤寒有五。有中风。有伤寒。有湿温。有热病。有温病。其所苦各不同。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100136,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。伤寒有几。其脉有变不。然。伤寒有五。有中风。有伤寒。有湿温。有热病。有温病。其所苦各不同。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '8JUFq9AxEPb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rTB2gHPeaSd', 4, '{"title":"第20100137条・五十八难","description":"<p>2、中风之脉。阳浮而滑。阴濡而弱。湿温之脉。阳濡而弱。阴小而急。伤寒之脉。阴阳俱盛而紧涩。热病之脉。阴阳俱浮。浮之而滑。沉之散涩。温病之脉。行在诸经。不知何经之动也。各随其经所在而取之。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100137,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2、中风之脉。阳浮而滑。阴濡而弱。湿温之脉。阳濡而弱。阴小而急。伤寒之脉。阴阳俱盛而紧涩。热病之脉。阴阳俱浮。浮之而滑。沉之散涩。温病之脉。行在诸经。不知何经之动也。各随其经所在而取之。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '8JUFq9AxEPb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ejN1dX6O77O', 4, '{"title":"第20100138条・五十八难","description":"<p>3、伤寒有汗出而愈。下之而死者。有汗出而死。下之而愈者。何也。然。阳虚阴盛。汗出而愈。下之即死。阳盛阴虚。汗出而死。下之而愈。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100138,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '3、伤寒有汗出而愈。下之而死者。有汗出而死。下之而愈者。何也。然。阳虚阴盛。汗出而愈。下之即死。阳盛阴虚。汗出而死。下之而愈。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '8JUFq9AxEPb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Hl2OW4AUoS', 4, '{"title":"第20100139条・五十八难","description":"<p>4、寒热之病。候之如何也。然。皮寒热者。皮不可近席。毛发焦。鼻槁。不得汗。肌寒热者。肌痛。唇舌槁。无汗。骨寒热者。病无所安。汗注不休。齿本槁痛。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100139,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '4、寒热之病。候之如何也。然。皮寒热者。皮不可近席。毛发焦。鼻槁。不得汗。肌寒热者。肌痛。唇舌槁。无汗。骨寒热者。病无所安。汗注不休。齿本槁痛。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '8JUFq9AxEPb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8iTdxdjmn05', 4, '{"title":"第20100140条・五十九难","description":"<p>1、曰。狂癫之病。何以别之。然。狂疾之始发。少卧而不饥。自高贤也。自辨智也。自贵倨也。妄笑好歌乐。妄行不休是也。癫疾始发。意不乐。僵仆直视。其脉三部阴阳俱盛是也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100140,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。狂癫之病。何以别之。然。狂疾之始发。少卧而不饥。自高贤也。自辨智也。自贵倨也。妄笑好歌乐。妄行不休是也。癫疾始发。意不乐。僵仆直视。其脉三部阴阳俱盛是也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '9T2reSqxos6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mU8Ycq54vMh', 4, '{"title":"第20100141条・六十难","description":"<p>1、曰。头心之病。有厥痛。有真痛。何谓也。然。手三阳之脉。受风寒。伏留而不去者。则名厥头痛。入连在脑者。名真头痛。其五脏气相干。名厥心痛。其痛甚。但在心。手足青者。即名真心痛。其真心痛者。旦发夕死。夕发旦死。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100141,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。头心之病。有厥痛。有真痛。何谓也。然。手三阳之脉。受风寒。伏留而不去者。则名厥头痛。入连在脑者。名真头痛。其五脏气相干。名厥心痛。其痛甚。但在心。手足青者。即名真心痛。其真心痛者。旦发夕死。夕发旦死。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'chFYIEIlE0s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OQYcWuLC0nN', 4, '{"title":"第20100142条・六十一难","description":"<p>1、曰。经言。望而知之谓之神。闻而知之谓之圣。问而知之谓之工。切脉而知之谓之巧。何谓也。然。望而知之者。望见其五色。以知其病。闻而知之者。闻其五音。以别其病。问而知之者。问其所欲五味。以知其病所起所在也。切脉而知之者。诊其寸口。视其虚实。以知其病。病在何脏腑也。经言。以外知之曰圣。以内知之曰神。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100142,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。经言。望而知之谓之神。闻而知之谓之圣。问而知之谓之工。切脉而知之谓之巧。何谓也。然。望而知之者。望见其五色。以知其病。闻而知之者。闻其五音。以别其病。问而知之者。问其所欲五味。以知其病所起所在也。切脉而知之者。诊其寸口。视其虚实。以知其病。病在何脏腑也。经言。以外知之曰圣。以内知之曰神。此之谓也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'uB71sfbiDy6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iJ5Kdmh5N0X', 4, '{"title":"第20100143条・六十二难","description":"<p>1、曰。脏井。荥有五。腑独有六者。何谓也。然。腑者。阳也。三焦行于诸阳。故置一俞。名曰原。腑有六者。亦与三焦共一气也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100143,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '2024-09-26T13:56:12.000Z', '1、曰。脏井。荥有五。腑独有六者。何谓也。然。腑者。阳也。三焦行于诸阳。故置一俞。名曰原。腑有六者。亦与三焦共一气也。', '2024-09-26T13:56:12.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'ZBsHCPKTnmi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8DAmulScp2x', 4, '{"title":"第20100144条・六十三难","description":"<p>1、曰。《十变》言。五脏六腑荥。合。皆以井为始者。何也。然。井者。东方春也。万物之始生。诸蚑行喘息。蚏飞蠕动。当生之物。莫不以春生。故岁数始于春。日数始于甲。故以井为始也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100144,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。《十变》言。五脏六腑荥。合。皆以井为始者。何也。然。井者。东方春也。万物之始生。诸蚑行喘息。蚏飞蠕动。当生之物。莫不以春生。故岁数始于春。日数始于甲。故以井为始也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'jj9iLd2qY0u');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CouP404NsjZ', 4, '{"title":"第20100145条・六十四难","description":"<p>1、曰。《十变》又言。阴井木。阳井金。阴荥火。阳荥水。阴俞土。阳俞木。阴经金。阳经火。阴合水。阳合土。阴阳皆不同。其意何也。然。是刚柔之事也。阴井乙木。阳井庚金。阳井庚。庚者。乙之刚也。阴井乙。乙者。庚之柔也。乙为木。故言阴井木也。庚为金。故言阳井金也。余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100145,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。《十变》又言。阴井木。阳井金。阴荥火。阳荥水。阴俞土。阳俞木。阴经金。阳经火。阴合水。阳合土。阴阳皆不同。其意何也。然。是刚柔之事也。阴井乙木。阳井庚金。阳井庚。庚者。乙之刚也。阴井乙。乙者。庚之柔也。乙为木。故言阴井木也。庚为金。故言阳井金也。余皆仿此。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'kIX7rMyolCc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dS0JZO4vDmj', 4, '{"title":"第20100146条・六十五难","description":"<p>1、曰。经言。所出为井。所入为合。其法奈何。然。所出为井。井者。东方春也。万物之始生。故言所出为井也。所入为合。合者。北方冬也。阳气入藏。故言所入为合也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100146,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。所出为井。所入为合。其法奈何。然。所出为井。井者。东方春也。万物之始生。故言所出为井也。所入为合。合者。北方冬也。阳气入藏。故言所入为合也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'hX5PiDMlon3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w7RSDxnvYr4', 4, '{"title":"第20100147条・六十六难","description":"<p>1、曰。经言。肺之原。出于太渊。心之原。出于太陵。肝之原。出于太冲。脾之原。出于大白。肾之原。出于太溪。少阴之原。出于兑骨。胆之原。出于丘墟。胃之原。出于冲阳。三焦之原。出于阳池。膀胱之原。出于京骨。大肠之原。出于合谷。小肠之原。出于腕骨。十二经皆以俞为原者。何也。然。五脏俞者。三焦之所行。气之所留止也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100147,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。肺之原。出于太渊。心之原。出于太陵。肝之原。出于太冲。脾之原。出于大白。肾之原。出于太溪。少阴之原。出于兑骨。胆之原。出于丘墟。胃之原。出于冲阳。三焦之原。出于阳池。膀胱之原。出于京骨。大肠之原。出于合谷。小肠之原。出于腕骨。十二经皆以俞为原者。何也。然。五脏俞者。三焦之所行。气之所留止也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'vEs9VOkPv1f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YwepvDN7SYb', 4, '{"title":"第20100148条・六十六难","description":"<p>2、三焦所行之俞为原者。何也。然。脐下肾间动气者。人之生命也。十二经之根本也。故名曰原。三焦者。原气之别使也。主通行三气。经历于五脏六腑。原者。三焦之尊号也。故所止辄为原。五脏六腑之有病者。皆取其原也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100148,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2、三焦所行之俞为原者。何也。然。脐下肾间动气者。人之生命也。十二经之根本也。故名曰原。三焦者。原气之别使也。主通行三气。经历于五脏六腑。原者。三焦之尊号也。故所止辄为原。五脏六腑之有病者。皆取其原也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'vEs9VOkPv1f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wNxkDfjpR7k', 4, '{"title":"第20100149条・六十七难","description":"<p>1、曰。五脏募皆在阴。而俞皆在阳者。何谓也。然。阴病行阳。阳病行阴。故令募在阴。俞在阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100149,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。五脏募皆在阴。而俞皆在阳者。何谓也。然。阴病行阳。阳病行阴。故令募在阴。俞在阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'iN7Ix924znk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fmgs1vaTgLh', 4, '{"title":"第20100150条・六十八难","description":"<p>1、曰。五脏六腑。皆有井。荥。俞。经。合。皆何所主。然。经言所出为井。所流为荥。所注为俞。所行为经。所入为合。井主心下满。荥主身热。俞主体重节痛。经主喘咳寒热。合主逆气而泄。此五脏六腑井。荥。俞。经。合所主病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100150,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。五脏六腑。皆有井。荥。俞。经。合。皆何所主。然。经言所出为井。所流为荥。所注为俞。所行为经。所入为合。井主心下满。荥主身热。俞主体重节痛。经主喘咳寒热。合主逆气而泄。此五脏六腑井。荥。俞。经。合所主病也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'K8F5I2foylI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HDpTdKeihas', 4, '{"title":"第20100151条・六十九难","description":"<p>1、曰。经言。虚者补之。实者泻之。不实不虚。以经取之。何谓也。然。虚者补其母。实者泻其子。当先补之。然后泻之。不实不虚。以经取之者。是正经自生病。不中他邪也。当自取其经。故言以经取之。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100151,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。虚者补之。实者泻之。不实不虚。以经取之。何谓也。然。虚者补其母。实者泻其子。当先补之。然后泻之。不实不虚。以经取之者。是正经自生病。不中他邪也。当自取其经。故言以经取之。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'T8xYJuNjH98');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fNde4Ldt5cc', 4, '{"title":"第20100152条・七十难","description":"<p>1、曰。春夏刺浅。秋冬刺深者。何谓也。然。春夏者。阳气在上。人气亦在上。故当浅取之。秋冬者。阳气在下。人气亦在下。故当深取之。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100152,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。春夏刺浅。秋冬刺深者。何谓也。然。春夏者。阳气在上。人气亦在上。故当浅取之。秋冬者。阳气在下。人气亦在下。故当深取之。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4a5zRsikNNk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jfik2V2GDCA', 4, '{"title":"第20100153条・七十难","description":"<p>2、春夏各致一阴。秋冬各致一阳者。何谓也。然。春夏温。必致一阴者。初下针。沉之至肾肝之部。得气。引持之阴也。秋冬寒。必致一阳者。初内针。浅而浮之至心肺之部。得气。推内之阳也。是谓春夏必致一阴。秋冬必致一阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100153,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2、春夏各致一阴。秋冬各致一阳者。何谓也。然。春夏温。必致一阴者。初下针。沉之至肾肝之部。得气。引持之阴也。秋冬寒。必致一阳者。初内针。浅而浮之至心肺之部。得气。推内之阳也。是谓春夏必致一阴。秋冬必致一阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '4a5zRsikNNk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EYMazQn2pvx', 4, '{"title":"第20100154条・七十一难","description":"<p>1、曰。经言。刺荣无伤卫。刺卫无伤荣。何谓也。然。针阳者。卧针而刺之。刺阴者。先以左手摄按所针荥俞之处。气散乃内针。是谓刺荣无伤卫。刺卫无伤荣也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100154,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。刺荣无伤卫。刺卫无伤荣。何谓也。然。针阳者。卧针而刺之。刺阴者。先以左手摄按所针荥俞之处。气散乃内针。是谓刺荣无伤卫。刺卫无伤荣也。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Fj4DqZBGG6f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SQ0CGMb9WVe', 4, '{"title":"第20100155条・七十二难","description":"<p>1、曰。经言。能知迎随之气。可令调之。调气之方。必在阴阳。何谓也。然。所谓迎随者。知荣卫之流行。经脉之往来也。随其逆顺而取之。故曰迎随。调气之方。必在阴阳者。知其内外表里。随其阴阳而调之。故曰调气之方。必在阴阳。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100155,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '2024-09-26T13:56:13.000Z', '1、曰。经言。能知迎随之气。可令调之。调气之方。必在阴阳。何谓也。然。所谓迎随者。知荣卫之流行。经脉之往来也。随其逆顺而取之。故曰迎随。调气之方。必在阴阳者。知其内外表里。随其阴阳而调之。故曰调气之方。必在阴阳。', '2024-09-26T13:56:13.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '3fbhFdNShAN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f5e6KfBMklz', 4, '{"title":"第20100156条・七十三难","description":"<p>1、曰。诸井者。肌肉浅薄。气少不足使也。刺之奈何。然。诸井者。木也。荥者。火也。火者。木之子。当刺井者。以荥泻之。故经言。补者不可以为泻。泻者不可以为补。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100156,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。诸井者。肌肉浅薄。气少不足使也。刺之奈何。然。诸井者。木也。荥者。火也。火者。木之子。当刺井者。以荥泻之。故经言。补者不可以为泻。泻者不可以为补。此之谓也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', '7RZ9W2zubNS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Py9a7yk3Gdp', 4, '{"title":"第20100157条・七十四难","description":"<p>1、曰。经言。春刺井。夏刺荥。季夏刺俞。秋刺经。冬刺合者。何谓也。然。春刺井者。邪在肝。夏刺荥者。邪在心。季夏刺俞者。邪在脾。秋刺经者。邪在肺。冬刺合者。邪在肾。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100157,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。春刺井。夏刺荥。季夏刺俞。秋刺经。冬刺合者。何谓也。然。春刺井者。邪在肝。夏刺荥者。邪在心。季夏刺俞者。邪在脾。秋刺经者。邪在肺。冬刺合者。邪在肾。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'kqd3xvEDFRs');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SLoKFfsS7MF', 4, '{"title":"第20100158条・七十四难","description":"<p>2、其肝。心。脾。肺。肾。而系于春。夏。秋。冬者。何也。然。五脏一病。辄有五也$l{一本言五色}。假令肝病。色青者肝也。臊臭者肝也。喜酸者肝也。喜呼者肝也。喜泣者。肝也。其病众多。不可尽言也。四时有数。而并系于春。夏。秋。冬者也。针之要妙。在于秋毫者也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100158,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2、其肝。心。脾。肺。肾。而系于春。夏。秋。冬者。何也。然。五脏一病。辄有五也$l{一本言五色}。假令肝病。色青者肝也。臊臭者肝也。喜酸者肝也。喜呼者肝也。喜泣者。肝也。其病众多。不可尽言也。四时有数。而并系于春。夏。秋。冬者也。针之要妙。在于秋毫者也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'kqd3xvEDFRs');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kGguYoHT33t', 4, '{"title":"第20100159条・七十五难","description":"<p>1、曰。经言。东方实。西方虚。泻南方。补北方。何谓也。然。金。木。水。火。土。当更相平。东方木也。西方金也。木欲实。金当平之。火欲实。水当平之。土欲实。木当平之。金欲实。火当平之。水欲实。土当平之。东方肝也。则知肝实。西方肺也。则知肺虚。泻南方火。补北方水。南方火。火者。木之子也。北方水。水者。木之母也。水胜火。子能令母实。母能令子虚。故泻火补水。欲令金不得平木也。经曰。不能治其虚。何问其余。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100159,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。东方实。西方虚。泻南方。补北方。何谓也。然。金。木。水。火。土。当更相平。东方木也。西方金也。木欲实。金当平之。火欲实。水当平之。土欲实。木当平之。金欲实。火当平之。水欲实。土当平之。东方肝也。则知肝实。西方肺也。则知肺虚。泻南方火。补北方水。南方火。火者。木之子也。北方水。水者。木之母也。水胜火。子能令母实。母能令子虚。故泻火补水。欲令金不得平木也。经曰。不能治其虚。何问其余。此之谓也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'fsu8Q1qeZ7y');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Psb5szM0Os8', 4, '{"title":"第20100160条・七十六难","description":"<p>1、曰。何谓补泻。当补之时。何所取气。当泻之时。何所置气。然。当补之时。从卫取气。当泻之时。从荣置气。其阳气不足。阴气有余。当先补其阳。而后泻其阴。阴气不足。阳气有余。当先补其阴。而后泻其阳。营卫通行。此其要也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100160,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。何谓补泻。当补之时。何所取气。当泻之时。何所置气。然。当补之时。从卫取气。当泻之时。从荣置气。其阳气不足。阴气有余。当先补其阳。而后泻其阴。阴气不足。阳气有余。当先补其阴。而后泻其阳。营卫通行。此其要也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'Tl8kmKMLqCn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3uzvUFGsMv6', 4, '{"title":"第20100161条・七十七难","description":"<p>1、曰。经言。上工治未病。中工治已病。何谓也。然。所谓治未病者。见肝之病。则知肝当传之与脾。故先实其脾气。无令得受肝之邪。故曰治未病焉。中工者。见肝之病。不晓相传。但一心治肝。故曰治已病也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100161,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。上工治未病。中工治已病。何谓也。然。所谓治未病者。见肝之病。则知肝当传之与脾。故先实其脾气。无令得受肝之邪。故曰治未病焉。中工者。见肝之病。不晓相传。但一心治肝。故曰治已病也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'muLwc6HMnjw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eHRILiKxwZS', 4, '{"title":"第20100162条・七十八难","description":"<p>1、曰。针有补泻。何谓也。然。补泻之法。非必呼吸出内针也。知为针者。信其左。不知为针者。信其右。当刺之时。先以左手厌按所针荥。俞之处。弹面努之。爪而下之。其气之来。如动脉之状。顺针而刺之。得气。因推而内之。是谓补。动而伸之。是谓泻。不得气。乃与。男外女内。不得气。是为十死不治也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100162,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。针有补泻。何谓也。然。补泻之法。非必呼吸出内针也。知为针者。信其左。不知为针者。信其右。当刺之时。先以左手厌按所针荥。俞之处。弹面努之。爪而下之。其气之来。如动脉之状。顺针而刺之。得气。因推而内之。是谓补。动而伸之。是谓泻。不得气。乃与。男外女内。不得气。是为十死不治也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'oudBDravpli');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PhT5i8xh8tt', 4, '{"title":"第20100163条・七十九难","description":"<p>1、曰。经言。迎而夺之。安得无虚。随而济之。安得无实。虚之与实。若得若失。实之与虚。若有若无。何谓也。然。迎而夺之者。泻其子也。随而济之者。补其母也。假令心病。泻手心主俞。是谓迎而夺之者也。补手心主井。是谓随而济之者也。所谓实之与虚者。牢濡之意也。气来实牢者为得。濡虚者为失。故曰若得若失也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100163,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。迎而夺之。安得无虚。随而济之。安得无实。虚之与实。若得若失。实之与虚。若有若无。何谓也。然。迎而夺之者。泻其子也。随而济之者。补其母也。假令心病。泻手心主俞。是谓迎而夺之者也。补手心主井。是谓随而济之者也。所谓实之与虚者。牢濡之意也。气来实牢者为得。濡虚者为失。故曰若得若失也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'E9pAdZHgDSF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kylrq4VoTEJ', 4, '{"title":"第20100164条・八十难","description":"<p>1、曰。经言。有见如入。有见如出者。何谓也。然。所谓有见如入。有见如出者。谓左手见气来至。乃内针。针入。见气尽。乃出针。是谓有见如入。有见如出也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100164,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。有见如入。有见如出者。何谓也。然。所谓有见如入。有见如出者。谓左手见气来至。乃内针。针入。见气尽。乃出针。是谓有见如入。有见如出也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'SUK2kdP90Ib');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iiZFod7q1gz', 4, '{"title":"第20100165条・八十一难","description":"<p>1、曰。经言。无实实虚虚。损不足而益有余。是寸口脉耶。将病自有虚实耶。其损益奈何。然。是病。非谓寸口脉也。谓病自有虚实也。假令肝实而肺虚。肝者木也。肺者金也。金木当更相平。当知金平木。假令肺实而肝虚。微少气。用针不补其肝。而反重实其肺。故曰实实虚虚。损不足而益有余。此者。中工之所害也。</p>","content_format":"html","_microfeed":{"bookId":"tZYk25WiJ0R","receiptNo":20100165,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '2024-09-26T13:56:14.000Z', '1、曰。经言。无实实虚虚。损不足而益有余。是寸口脉耶。将病自有虚实耶。其损益奈何。然。是病。非谓寸口脉也。谓病自有虚实也。假令肝实而肺虚。肝者木也。肺者金也。金木当更相平。当知金平木。假令肺实而肝虚。微少气。用针不补其肝。而反重实其肺。故曰实实虚虚。损不足而益有余。此者。中工之所害也。', '2024-09-26T13:56:14.000Z', 1, NULL, 'tZYk25WiJ0R', 'section', 'mngZ60DWwSQ');
